  pi.on("session_start", (_e: any, ctx: any) => { restoreHookState(ctx.sessionManager?.getBranch?.() ?? ctx.sessionManager?.getEntries?.() ?? []); ctx.ui?.setWidget?.("swarm-hooks", undefined); });
