  "value": "{\"upstream/pi-mono/packages/coding-agent/src/core/extensions/types.ts\":\"/**\\n * Extension system types.\\n *\\n * Extensions are TypeScript modules that can:\\n * - Subscribe to agent lifecycle events\\n * - Register LLM-callable tools\\n * - Register commands, keyboard shortcuts, and CLI flags\\n * - Interact with the user via UI primitives\\n */\\n\\nimport type {\\n\\tAgentMessage,\\n\\tAgentToolResult,\\n\\tAgentToolUpdateCallback,\\n\\tThinkingLevel,\\n\\tToolExecutionMode,\\n} from \\\"@earendil-works/pi-agent-core\\\";\\nimport type {\\n\\tApi,\\n\\tAssistantMessageEvent,\\n\\tAssistantMessageEventStream,\\n\\tContext,\\n\\tImageContent,\\n\\tModel,\\n\\tOAuthCredentials,\\n\\tOAuthLoginCallbacks,\\n\\tSimpleStreamOptions,\\n\\tTextContent,\\n\\tToolResultMessage,\\n} from \\\"@earendil-works/pi-ai\\\";\\nimport type {\\n\\tAutocompleteItem,\\n\\tAutocompleteProvider,\\n\\tComponent,\\n\\tEditorComponent,\\n\\tEditorTheme,\\n\\tKeyId,\\n\\tOverlayHandle,\\n\\tOverlayOptions,\\n\\tTUI,\\n} from \\\"@earendil-works/pi-tui\\\";\\nimport type { Static, TSchema } from \\\"typebox\\\";\\nimport type { Theme } from \\\"../../modes/interactive/theme/theme.ts\\\";\\nimport type { BashResult } from \\\"../bash-executor.ts\\\";\\nimport type { CompactionPreparation, CompactionResult } from \\\"../compaction/index.ts\\\";\\nimport type { EventBus } from \\\"../event-bus.ts\\\";\\nimport type { ExecOptions, ExecResult } from \\\"../exec.ts\\\";\\nimport type { ReadonlyFooterDataProvider } from \\\"../footer-data-provider.ts\\\";\\nimport type { KeybindingsManager } from \\\"../keybindings.ts\\\";\\nimport type { CustomMessage } from \\\"../messages.ts\\\";\\nimport type { ModelRegistry } from \\\"../model-registry.ts\\\";\\nimport type {\\n\\tBranchSummaryEntry,\\n\\tCompactionEntry,\\n\\tReadonlySessionManager,\\n\\tSessionEntry,\\n\\tSessionManager,\\n} from \\\"../session-manager.ts\\\";\\nimport type { SlashCommandInfo } from \\\"../slash-commands.ts\\\";\\nimport type { SourceInfo } from \\\"../source-info.ts\\\";\\nimport type { BuildSystemPromptOptions } from \\\"../system-prompt.ts\\\";\\nimport type { BashOperations } from \\\"../tools/bash.ts\\\";\\nimport type { EditToolDetails } from \\\"../tools/edit.ts\\\";\\nimport type {\\n\\tBashToolDetails,\\n\\tBashToolInput,\\n\\tEditToolInput,\\n\\tFindToolDetails,\\n\\tFindToolInput,\\n\\tGrepToolDetails,\\n\\tGrepToolInput,\\n\\tLsToolDetails,\\n\\tLsToolInput,\\n\\tReadToolDetails,\\n\\tReadToolInput,\\n\\tWriteToolInput,\\n} from \\\"../tools/index.ts\\\";\\n\\nexport type { ExecOptions, ExecResult } from \\\"../exec.ts\\\";\\nexport type { BuildSystemPromptOptions } from \\\"../system-prompt.ts\\\";\\nexport type { AgentToolResult, AgentToolUpdateCallback, ToolExecutionMode };\\nexport type { AppKeybinding, KeybindingsManager } from \\\"../keybindings.ts\\\";\\n\\n// ============================================================================\\n// UI Context\\n// ============================================================================\\n\\n/** Options for extension UI dialogs. */\\nexport interface ExtensionUIDialogOptions {\\n\\t/** AbortSignal to programmatically dismiss the dialog. */\\n\\tsignal?: AbortSignal;\\n\\t/** Timeout in milliseconds. Dialog auto-dismisses with live countdown display. */\\n\\ttimeout?: number;\\n}\\n\\n/** Placement for extension widgets. */\\nexport type WidgetPlacement = \\\"aboveEditor\\\" | \\\"belowEditor\\\";\\n\\n/** Options for extension widgets. */\\nexport interface ExtensionWidgetOptions {\\n\\t/** Where the widget is rendered. Defaults to \\\"aboveEditor\\\". */\\n\\tplacement?: WidgetPlacement;\\n}\\n\\n/** Raw terminal input listener for extensions. */\\nexport type TerminalInputHandler = (data: string) => { consume?: boolean; data?: string } | undefined;\\n\\n/** Working indicator configuration for the interactive streaming loader. */\\nexport interface WorkingIndicatorOptions {\\n\\t/** Animation frames. Use an empty array to hide the indicator entirely. Custom frames are rendered verbatim. */\\n\\tframes?: string[];\\n\\t/** Frame interval in milliseconds for animated indicators. */\\n\\tintervalMs?: number;\\n}\\n\\n/** Wrap the current autocomplete provider with additional behavior. */\\nexport type AutocompleteProviderFactory = (current: AutocompleteProvider) => AutocompleteProvider;\\nexport type EditorFactory = (tui: TUI, theme: EditorTheme, keybindings: KeybindingsManager) => EditorComponent;\\n\\n/**\\n * UI context for extensions to request interactive UI.\\n * Each mode (interactive, RPC, print) provides its own implementation.\\n */\\nexport interface ExtensionUIContext {\\n\\t/** Show a selector and return the user's choice. */\\n\\tselect(title: string, options: string[], opts?: ExtensionUIDialogOptions): Promise<string | undefined>;\\n\\n\\t/** Show a confirmation dialog. */\\n\\tconfirm(title: string, message: string, opts?: ExtensionUIDialogOptions): Promise<boolean>;\\n\\n\\t/** Show a text input dialog. */\\n\\tinput(title: string, placeholder?: string, opts?: ExtensionUIDialogOptions): Promise<string | undefined>;\\n\\n\\t/** Show a notification to the user. */\\n\\tnotify(message: string, type?: \\\"info\\\" | \\\"warning\\\" | \\\"error\\\"): void;\\n\\n\\t/** Listen to raw terminal input (interactive mode only). Returns an unsubscribe function. */\\n\\tonTerminalInput(handler: TerminalInputHandler): () => void;\\n\\n\\t/** Set status text in the footer/status bar. Pass undefined to clear. */\\n\\tsetStatus(key: string, text: string | undefined): void;\\n\\n\\t/** Set the working/loading message shown during streaming. Call with no argument to restore default. */\\n\\tsetWorkingMessage(message?: string): void;\\n\\n\\t/** Show or hide the built-in interactive working loader row during streaming. */\\n\\tsetWorkingVisible(visible: boolean): void;\\n\\n\\t/**\\n\\t * Configure the interactive working indicator shown during streaming.\\n\\t *\\n\\t * - Omit the argument to restore the default animated spinner.\\n\\t * - Use `frames: [\\\"●\\\"]` for a static indicator.\\n\\t * - Use `frames: []` to hide the indicator entirely.\\n\\t * - Custom frames are rendered as provided, so extensions must add their own colors.\\n\\t */\\n\\tsetWorkingIndicator(options?: WorkingIndicatorOptions): void;\\n\\n\\t/** Set the label shown for hidden thinking blocks. Call with no argument to restore default. */\\n\\tsetHiddenThinkingLabel(label?: string): void;\\n\\n\\t/** Set a widget to display above or below the editor. Accepts string array or component factory. */\\n\\tsetWidget(key: string, content: string[] | undefined, options?: ExtensionWidgetOptions): void;\\n\\tsetWidget(\\n\\t\\tkey: string,\\n\\t\\tcontent: ((tui: TUI, theme: Theme) => Component & { dispose?(): void }) | undefined,\\n\\t\\toptions?: ExtensionWidgetOptions,\\n\\t): void;\\n\\n\\t/** Set a custom footer component, or undefined to restore the built-in footer.\\n\\t *\\n\\t * The factory receives a FooterDataProvider for data not otherwise accessible:\\n\\t * git branch and extension statuses from setStatus(). Token stats, model info,\\n\\t * etc. are available via ctx.sessionManager and ctx.model.\\n\\t */\\n\\tsetFooter(\\n\\t\\tfactory:\\n\\t\\t\\t| ((tui: TUI, theme: Theme, footerData: ReadonlyFooterDataProvider) => Component & { dispose?(): void })\\n\\t\\t\\t| undefined,\\n\\t): void;\\n\\n\\t/** Set a custom header component (shown at startup, above chat), or undefined to restore the built-in header. */\\n\\tsetHeader(factory: ((tui: TUI, theme: Theme) => Component & { dispose?(): void }) | undefined): void;\\n\\n\\t/** Set the terminal window/tab title. */\\n\\tsetTitle(title: string): void;\\n\\n\\t/** Show a custom component with keyboard focus. */\\n\\tcustom<T>(\\n\\t\\tfactory: (\\n\\t\\t\\ttui: TUI,\\n\\t\\t\\ttheme: Theme,\\n\\t\\t\\tkeybindings: KeybindingsManager,\\n\\t\\t\\tdone: (result: T) => void,\\n\\t\\t) => (Component & { dispose?(): void }) | Promise<Component & { dispose?(): void }>,\\n\\t\\toptions?: {\\n\\t\\t\\toverlay?: boolean;\\n\\t\\t\\t/** Overlay positioning/sizing options. Can be static or a function for dynamic updates. */\\n\\t\\t\\toverlayOptions?: OverlayOptions | (() => OverlayOptions);\\n\\t\\t\\t/** Called with the overlay handle after the overlay is shown. Use to control visibility. */\\n\\t\\t\\tonHandle?: (handle: OverlayHandle) => void;\\n\\t\\t},\\n\\t): Promise<T>;\\n\\n\\t/** Paste text into the editor, triggering paste handling (collapse for large content). */\\n\\tpasteToEditor(text: string): void;\\n\\n\\t/** Set the text in the core input editor. */\\n\\tsetEditorText(text: string): void;\\n\\n\\t/** Get the current text from the core input editor. */\\n\\tgetEditorText(): string;\\n\\n\\t/** Show a multi-line editor for text editing. */\\n\\teditor(title: string, prefill?: string): Promise<string | undefined>;\\n\\n\\t/** Stack additional autocomplete behavior on top of the built-in provider. */\\n\\taddAutocompleteProvider(factory: AutocompleteProviderFactory): void;\\n\\n\\t/**\\n\\t * Set a custom editor component via factory function.\\n\\t * Pass undefined to restore the default editor.\\n\\t *\\n\\t * The factory receives:\\n\\t * - `theme`: EditorTheme for styling borders and autocomplete\\n\\t * - `keybindings`: KeybindingsManager for app-level keybindings\\n\\t *\\n\\t * For full app keybinding support (escape, ctrl+d, model switching, etc.),\\n\\t * extend `CustomEditor` from `@earendil-works/pi-coding-agent` and call\\n\\t * `super.handleInput(data)` for keys you don't handle.\\n\\t *\\n\\t * @example\\n\\t * ```ts\\n\\t * import { CustomEditor } from \\\"@earendil-works/pi-coding-agent\\\";\\n\\t *\\n\\t * class VimEditor extends CustomEditor {\\n\\t *   private mode: \\\"normal\\\" | \\\"insert\\\" = \\\"insert\\\";\\n\\t *\\n\\t *   handleInput(data: string): void {\\n\\t *     if (this.mode === \\\"normal\\\") {\\n\\t *       // Handle vim normal mode keys...\\n\\t *       if (data === \\\"i\\\") { this.mode = \\\"insert\\\"; return; }\\n\\t *     }\\n\\t *     super.handleInput(data);  // App keybindings + text editing\\n\\t *   }\\n\\t * }\\n\\t *\\n\\t * ctx.ui.setEditorComponent((tui, theme, keybindings) =>\\n\\t *   new VimEditor(tui, theme, keybindings)\\n\\t * );\\n\\t * ```\\n\\t */\\n\\tsetEditorComponent(factory: EditorFactory | undefined): void;\\n\\n\\t/** Get the currently configured custom editor factory, or undefined when using the default editor. */\\n\\tgetEditorComponent(): EditorFactory | undefined;\\n\\n\\t/** Get the current theme for styling. */\\n\\treadonly theme: Theme;\\n\\n\\t/** Get all available themes with their names and file paths. */\\n\\tgetAllThemes(): { name: string; path: string | undefined }[];\\n\\n\\t/** Load a theme by name without switching to it. Returns undefined if not found. */\\n\\tgetTheme(name: string): Theme | undefined;\\n\\n\\t/** Set the current theme by name or Theme object. */\\n\\tsetTheme(theme: string | Theme): { success: boolean; error?: string };\\n\\n\\t/** Get current tool output expansion state. */\\n\\tgetToolsExpanded(): boolean;\\n\\n\\t/** Set tool output expansion state. */\\n\\tsetToolsExpanded(expanded: boolean): void;\\n}\\n\\n// ============================================================================\\n// Extension Context\\n// ============================================================================\\n\\nexport interface ContextUsage {\\n\\t/** Estimated context tokens, or null if unknown (e.g. right after compaction, before next LLM response). */\\n\\ttokens: number | null;\\n\\tcontextWindow: number;\\n\\t/** Context usage as percentage of context window, or null if tokens is unknown. */\\n\\tpercent: number | null;\\n}\\n\\nexport interface CompactOptions {\\n\\tcustomInstructions?: string;\\n\\tonComplete?: (result: CompactionResult) => void;\\n\\tonError?: (error: Error) => void;\\n}\\n\\n/**\\n * Context passed to extension event handlers.\\n */\\nexport type ExtensionMode = \\\"tui\\\" | \\\"rpc\\\" | \\\"json\\\" | \\\"print\\\";\\n\\nexport interface ExtensionContext {\\n\\t/** UI methods for user interaction */\\n\\tui: ExtensionUIContext;\\n\\t/** Current run mode. Use \\\"tui\\\" to guard terminal-only UI such as custom components. */\\n\\tmode: ExtensionMode;\\n\\t/** Whether dialog-capable UI is available (true in TUI and RPC modes) */\\n\\thasUI: boolean;\\n\\t/** Current working directory */\\n\\tcwd: string;\\n\\t/** Session manager (read-only) */\\n\\tsessionManager: ReadonlySessionManager;\\n\\t/** Model registry for API key resolution */\\n\\tmodelRegistry: ModelRegistry;\\n\\t/** Current model (may be undefined) */\\n\\tmodel: Model<any> | undefined;\\n\\t/** Whether the agent is idle (not streaming) */\\n\\tisIdle(): boolean;\\n\\t/** The current abort signal, or undefined when the agent is not streaming. */\\n\\tsignal: AbortSignal | undefined;\\n\\t/** Abort the current agent operation */\\n\\tabort(): void;\\n\\t/** Whether there are queued messages waiting */\\n\\thasPendingMessages(): boolean;\\n\\t/** Gracefully shutdown pi and exit. Available in all contexts. */\\n\\tshutdown(): void;\\n\\t/** Get current context usage for the active model. */\\n\\tgetContextUsage(): ContextUsage | undefined;\\n\\t/** Trigger compaction without awaiting completion. */\\n\\tcompact(options?: CompactOptions): void;\\n\\t/** Get the current effective system prompt. */\\n\\tgetSystemPrompt(): string;\\n}\\n\\n/**\\n * Extended context for command handlers.\\n * Includes session control methods only safe in user-initiated commands.\\n */\\nexport interface ExtensionCommandContext extends ExtensionContext {\\n\\t/** Get the current base system-prompt construction options. */\\n\\tgetSystemPromptOptions(): BuildSystemPromptOptions;\\n\\n\\t/** Wait for the agent to finish streaming */\\n\\twaitForIdle(): Promise<void>;\\n\\n\\t/** Start a new session, optionally with initialization. */\\n\\tnewSession(options?: {\\n\\t\\tparentSession?: string;\\n\\t\\tsetup?: (sessionManager: SessionManager) => Promise<void>;\\n\\t\\twithSession?: (ctx: ReplacedSessionContext) => Promise<void>;\\n\\t}): Promise<{ cancelled: boolean }>;\\n\\n\\t/** Fork from a specific entry, creating a new session file. */\\n\\tfork(\\n\\t\\tentryId: string,\\n\\t\\toptions?: { position?: \\\"before\\\" | \\\"at\\\"; withSession?: (ctx: ReplacedSessionContext) => Promise<void> },\\n\\t): Promise<{ cancelled: boolean }>;\\n\\n\\t/** Navigate to a different point in the session tree. */\\n\\tnavigateTree(\\n\\t\\ttargetId: string,\\n\\t\\toptions?: { summarize?: boolean; customInstructions?: string; replaceInstructions?: boolean; label?: string },\\n\\t): Promise<{ cancelled: boolean }>;\\n\\n\\t/** Switch to a different session file. */\\n\\tswitchSession(\\n\\t\\tsessionPath: string,\\n\\t\\toptions?: { withSession?: (ctx: ReplacedSessionContext) => Promise<void> },\\n\\t): Promise<{ cancelled: boolean }>;\\n\\n\\t/** Reload extensions, skills, prompts, and themes. */\\n\\treload(): Promise<void>;\\n}\\n\\n/**\\n * Fresh command-capable context bound to the replacement session after a session switch.\\n *\\n * This is passed to `withSession()` callbacks on `newSession()`, `fork()`, and `switchSession()`.\\n */\\nexport interface ReplacedSessionContext extends ExtensionCommandContext {\\n\\tsendMessage<T = unknown>(\\n\\t\\tmessage: Pick<CustomMessage<T>, \\\"customType\\\" | \\\"content\\\" | \\\"display\\\" | \\\"details\\\">,\\n\\t\\toptions?: { triggerTurn?: boolean; deliverAs?: \\\"steer\\\" | \\\"followUp\\\" | \\\"nextTurn\\\" },\\n\\t): Promise<void>;\\n\\n\\tsendUserMessage(\\n\\t\\tcontent: string | (TextContent | ImageContent)[],\\n\\t\\toptions?: { deliverAs?: \\\"steer\\\" | \\\"followUp\\\" },\\n\\t): Promise<void>;\\n}\\n\\n// ============================================================================\\n// Tool Types\\n// ============================================================================\\n\\n/** Rendering options for tool results */\\nexport interface ToolRenderResultOptions {\\n\\t/** Whether the result view is expanded */\\n\\texpanded: boolean;\\n\\t/** Whether this is a partial/streaming result */\\n\\tisPartial: boolean;\\n}\\n\\n/** Context passed to tool renderers. */\\nexport interface ToolRenderContext<TState = any, TArgs = any> {\\n\\t/** Current tool call arguments. Shared across call/result renders for the same tool call. */\\n\\targs: TArgs;\\n\\t/** Unique id for this tool execution. Stable across call/result renders for the same tool call. */\\n\\ttoolCallId: string;\\n\\t/** Invalidate just this tool execution component for redraw. */\\n\\tinvalidate: () => void;\\n\\t/** Previously returned component for this render slot, if any. */\\n\\tlastComponent: Component | undefined;\\n\\t/** Shared renderer state for this tool row. Initialized by tool-execution.ts. */\\n\\tstate: TState;\\n\\t/** Working directory for this tool execution. */\\n\\tcwd: string;\\n\\t/** Whether the tool execution has started. */\\n\\texecutionStarted: boolean;\\n\\t/** Whether the tool call arguments are complete. */\\n\\targsComplete: boolean;\\n\\t/** Whether the tool result is partial/streaming. */\\n\\tisPartial: boolean;\\n\\t/** Whether the result view is expanded. */\\n\\texpanded: boolean;\\n\\t/** Whether inline images are currently shown in the TUI. */\\n\\tshowImages: boolean;\\n\\t/** Whether the current result is an error. */\\n\\tisError: boolean;\\n}\\n\\n/**\\n * Tool definition for registerTool().\\n */\\nexport interface ToolDefinition<TParams extends TSchema = TSchema, TDetails = unknown, TState = any> {\\n\\t/** Tool name (used in LLM tool calls) */\\n\\tname: string;\\n\\t/** Human-readable label for UI */\\n\\tlabel: string;\\n\\t/** Description for LLM */\\n\\tdescription: string;\\n\\t/** Optional one-line snippet for the Available tools section in the default system prompt. Custom tools are omitted from that section when this is not provided. */\\n\\tpromptSnippet?: string;\\n\\t/** Optional guideline bullets appended to the default system prompt Guidelines section when this tool is active. */\\n\\tpromptGuidelines?: string[];\\n\\t/** Parameter schema (TypeBox) */\\n\\tparameters: TParams;\\n\\t/** Controls whether ToolExecutionComponent renders the standard colored shell or the tool renders its own framing. */\\n\\trenderShell?: \\\"default\\\" | \\\"self\\\";\\n\\n\\t/** Optional compatibility shim to prepare raw tool call arguments before schema validation. Must return an object conforming to TParams. */\\n\\tprepareArguments?: (args: unknown) => Static<TParams>;\\n\\n\\t/**\\n\\t * Per-tool execution mode override.\\n\\t * - \\\"sequential\\\": this tool must execute one at a time with other tool calls.\\n\\t * - \\\"parallel\\\": this tool can execute concurrently with other tool calls.\\n\\t *\\n\\t * If omitted, the default execution mode applies.\\n\\t */\\n\\texecutionMode?: ToolExecutionMode;\\n\\n\\t/** Execute the tool. */\\n\\texecute(\\n\\t\\ttoolCallId: string,\\n\\t\\tparams: Static<TParams>,\\n\\t\\tsignal: AbortSignal | undefined,\\n\\t\\tonUpdate: AgentToolUpdateCallback<TDetails> | undefined,\\n\\t\\tctx: ExtensionContext,\\n\\t): Promise<AgentToolResult<TDetails>>;\\n\\n\\t/** Custom rendering for tool call display */\\n\\trenderCall?: (args: Static<TParams>, theme: Theme, context: ToolRenderContext<TState, Static<TParams>>) => Component;\\n\\n\\t/** Custom rendering for tool result display */\\n\\trenderResult?: (\\n\\t\\tresult: AgentToolResult<TDetails>,\\n\\t\\toptions: ToolRenderResultOptions,\\n\\t\\ttheme: Theme,\\n\\t\\tcontext: ToolRenderContext<TState, Static<TParams>>,\\n\\t) => Component;\\n}\\n\\ntype AnyToolDefinition = ToolDefinition<any, any, any>;\\n\\n/**\\n * Preserve parameter inference for standalone tool definitions.\\n *\\n * Use this when assigning a tool to a variable or passing it through arrays such\\n * as `customTools`, where contextual typing would otherwise widen params to\\n * `unknown`.\\n */\\nexport function defineTool<TParams extends TSchema, TDetails = unknown, TState = any>(\\n\\ttool: ToolDefinition<TParams, TDetails, TState>,\\n): ToolDefinition<TParams, TDetails, TState> & AnyToolDefinition {\\n\\treturn tool as ToolDefinition<TParams, TDetails, TState> & AnyToolDefinition;\\n}\\n\\n// ============================================================================\\n// Startup/Resource Events\\n// ============================================================================\\n\\nexport interface ProjectTrustEvent {\\n\\ttype: \\\"project_trust\\\";\\n\\tcwd: string;\\n}\\n\\nexport type ProjectTrustEventDecision = \\\"yes\\\" | \\\"no\\\" | \\\"undecided\\\";\\n\\nexport interface ProjectTrustEventResult {\\n\\ttrusted: ProjectTrustEventDecision;\\n\\tremember?: boolean;\\n}\\n\\nexport interface ProjectTrustContext {\\n\\tcwd: string;\\n\\tmode: ExtensionMode;\\n\\thasUI: boolean;\\n\\tui: Pick<ExtensionUIContext, \\\"select\\\" | \\\"confirm\\\" | \\\"input\\\" | \\\"notify\\\">;\\n}\\n\\nexport type ProjectTrustHandler = (\\n\\tevent: ProjectTrustEvent,\\n\\tctx: ProjectTrustContext,\\n) => Promise<ProjectTrustEventResult> | ProjectTrustEventResult;\\n\\n/** Fired after session_start to allow extensions to provide additional resource paths. */\\nexport interface ResourcesDiscoverEvent {\\n\\ttype: \\\"resources_discover\\\";\\n\\tcwd: string;\\n\\treason: \\\"startup\\\" | \\\"reload\\\";\\n}\\n\\n/** Result from resources_discover event handler */\\nexport interface ResourcesDiscoverResult {\\n\\tskillPaths?: string[];\\n\\tpromptPaths?: string[];\\n\\tthemePaths?: string[];\\n}\\n\\n// ============================================================================\\n// Session Events\\n// ============================================================================\\n\\n/** Fired when a session is started, loaded, or reloaded */\\nexport interface SessionStartEvent {\\n\\ttype: \\\"session_start\\\";\\n\\t/** Why this session start happened. */\\n\\treason: \\\"startup\\\" | \\\"reload\\\" | \\\"new\\\" | \\\"resume\\\" | \\\"fork\\\";\\n\\t/** Previously active session file. Present for \\\"new\\\", \\\"resume\\\", and \\\"fork\\\". */\\n\\tpreviousSessionFile?: string;\\n}\\n\\n/** Fired before switching to another session (can be cancelled) */\\nexport interface SessionBeforeSwitchEvent {\\n\\ttype: \\\"session_before_switch\\\";\\n\\treason: \\\"new\\\" | \\\"resume\\\";\\n\\ttargetSessionFile?: string;\\n}\\n\\n/** Fired before forking a session (can be cancelled) */\\nexport interface SessionBeforeForkEvent {\\n\\ttype: \\\"session_before_fork\\\";\\n\\tentryId: string;\\n\\tposition: \\\"before\\\" | \\\"at\\\";\\n}\\n\\n/** Fired before context compaction (can be cancelled or customized) */\\nexport interface SessionBeforeCompactEvent {\\n\\ttype: \\\"session_before_compact\\\";\\n\\tpreparation: CompactionPreparation;\\n\\tbranchEntries: SessionEntry[];\\n\\tcustomInstructions?: string;\\n\\tsignal: AbortSignal;\\n}\\n\\n/** Fired after context compaction */\\nexport interface SessionCompactEvent {\\n\\ttype: \\\"session_compact\\\";\\n\\tcompactionEntry: CompactionEntry;\\n\\tfromExtension: boolean;\\n}\\n\\n/** Fired before an extension runtime is torn down due to quit, reload, or session replacement. */\\nexport interface SessionShutdownEvent {\\n\\ttype: \\\"session_shutdown\\\";\\n\\treason: \\\"quit\\\" | \\\"reload\\\" | \\\"new\\\" | \\\"resume\\\" | \\\"fork\\\";\\n\\t/** Destination session file when shutting down due to session replacement. */\\n\\ttargetSessionFile?: string;\\n}\\n\\n/** Preparation data for tree navigation */\\nexport interface TreePreparation {\\n\\ttargetId: string;\\n\\toldLeafId: string | null;\\n\\tcommonAncestorId: string | null;\\n\\tentriesToSummarize: SessionEntry[];\\n\\tuserWantsSummary: boolean;\\n\\t/** Custom instructions for summarization */\\n\\tcustomInstructions?: string;\\n\\t/** If true, customInstructions replaces the default prompt instead of being appended */\\n\\treplaceInstructions?: boolean;\\n\\t/** Label to attach to the branch summary entry */\\n\\tlabel?: string;\\n}\\n\\n/** Fired before navigating in the session tree (can be cancelled) */\\nexport interface SessionBeforeTreeEvent {\\n\\ttype: \\\"session_before_tree\\\";\\n\\tpreparation: TreePreparation;\\n\\tsignal: AbortSignal;\\n}\\n\\n/** Fired after navigating in the session tree */\\nexport interface SessionTreeEvent {\\n\\ttype: \\\"session_tree\\\";\\n\\tnewLeafId: string | null;\\n\\toldLeafId: string | null;\\n\\tsummaryEntry?: BranchSummaryEntry;\\n\\tfromExtension?: boolean;\\n}\\n\\nexport type SessionEvent =\\n\\t| SessionStartEvent\\n\\t| SessionBeforeSwitchEvent\\n\\t| SessionBeforeForkEvent\\n\\t| SessionBeforeCompactEvent\\n\\t| SessionCompactEvent\\n\\t| SessionShutdownEvent\\n\\t| SessionBeforeTreeEvent\\n\\t| SessionTreeEvent;\\n\\n// ============================================================================\\n// Agent Events\\n// ============================================================================\\n\\n/** Fired before each LLM call. Can modify messages. */\\nexport interface ContextEvent {\\n\\ttype: \\\"context\\\";\\n\\tmessages: AgentMessage[];\\n}\\n\\n/** Fired before a provider request is sent. Can replace the payload. */\\nexport interface BeforeProviderRequestEvent {\\n\\ttype: \\\"before_provider_request\\\";\\n\\tpayload: unknown;\\n}\\n\\n/** Fired after a provider response is received and before the response stream is consumed. */\\nexport interface AfterProviderResponseEvent {\\n\\ttype: \\\"after_provider_response\\\";\\n\\tstatus: number;\\n\\theaders: Record<string, string>;\\n}\\n\\n/** Fired after user submits prompt but before agent loop. */\\nexport interface BeforeAgentStartEvent {\\n\\ttype: \\\"before_agent_start\\\";\\n\\t/** The raw user prompt text (after expansion). */\\n\\tprompt: string;\\n\\t/** Images