* Fired when a tool finishes executing */\\nexport interface ToolExecutionEndEvent {\\n\\ttype: \\\"tool_execution_end\\\";\\n\\ttoolCallId: string;\\n\\ttoolName: string;\\n\\tresult: any;\\n\\tisError: boolean;\\n}\\n\\n// ============================================================================\\n// Model Events\\n// ============================================================================\\n\\nexport type ModelSelectSource = \\\"set\\\" | \\\"cycle\\\" | \\\"restore\\\";\\n\\n/** Fired when a new model is selected */\\nexport interface ModelSelectEvent {\\n\\ttype: \\\"model_select\\\";\\n\\tmodel: Model<any>;\\n\\tpreviousModel: Model<any> | undefined;\\n\\tsource: ModelSelectSource;\\n}\\n\\n/** Fired when a new thinking level is selected */\\nexport interface ThinkingLevelSelectEvent {\\n\\ttype: \\\"thinking_level_select\\\";\\n\\tlevel: ThinkingLevel;\\n\\tpreviousLevel: ThinkingLevel;\\n}\\n\\n// ============================================================================\\n// User Bash Events\\n// ============================================================================\\n\\n/** Fired when user executes a bash command via ! or !! prefix */\\nexport interface UserBashEvent {\\n\\ttype: \\\"user_bash\\\";\\n\\t/** The command to execute */\\n\\tcommand: string;\\n\\t/** True if !! prefix was used (excluded from LLM context) */\\n\\texcludeFromContext: boolean;\\n\\t/** Current working directory */\\n\\tcwd: string;\\n}\\n\\n// ============================================================================\\n// Input Events\\n// ============================================================================\\n\\n/** Source of user input */\\nexport type InputSource = \\\"interactive\\\" | \\\"rpc\\\" | \\\"extension\\\";\\n\\n/** Fired when user input is received, before agent processing */\\nexport interface InputEvent {\\n\\ttype: \\\"input\\\";\\n\\t/** The input text */\\n\\ttext: string;\\n\\t/** Attached images, if any */\\n\\timages?: ImageContent[];\\n\\t/** Where the input came from */\\n\\tsource: InputSource;\\n\\t/** How the input will be delivered during streaming, or undefined when idle */\\n\\tstreamingBehavior?: \\\"steer\\\" | \\\"followUp\\\";\\n}\\n\\n/** Result from input event handler */\\nexport type InputEventResult =\\n\\t| { action: \\\"continue\\\" }\\n\\t| { action: \\\"transform\\\"; text: string; images?: ImageContent[] }\\n\\t| { action: \\\"handled\\\" };\\n\\n// ============================================================================\\n// Tool Events\\n// ============================================================================\\n\\ninterface ToolCallEventBase {\\n\\ttype: \\\"tool_call\\\";\\n\\ttoolCallId: string;\\n}\\n\\nexport interface BashToolCallEvent extends ToolCallEventBase {\\n\\ttoolName: \\\"bash\\\";\\n\\tinput: BashToolInput;\\n}\\n\\nexport interface ReadToolCallEvent extends ToolCallEventBase {\\n\\ttoolName: \\\"read\\\";\\n\\tinput: ReadToolInput;\\n}\\n\\nexport interface EditToolCallEvent extends ToolCallEventBase {\\n\\ttoolName: \\\"edit\\\";\\n\\tinput: EditToolInput;\\n}\\n\\nexport interface WriteToolCallEvent extends ToolCallEventBase {\\n\\ttoolName: \\\"write\\\";\\n\\tinput: WriteToolInput;\\n}\\n\\nexport interface GrepToolCallEvent extends ToolCallEventBase {\\n\\ttoolName: \\\"grep\\\";\\n\\tinput: GrepToolInput;\\n}\\n\\nexport interface FindToolCallEvent extends ToolCallEventBase {\\n\\ttoolName: \\\"find\\\";\\n\\tinput: FindToolInput;\\n}\\n\\nexport interface LsToolCallEvent extends ToolCallEventBase {\\n\\ttoolName: \\\"ls\\\";\\n\\tinput: LsToolInput;\\n}\\n\\nexport interface CustomToolCallEvent extends ToolCallEventBase {\\n\\ttoolName: string;\\n\\tinput: Record<string, unknown>;\\n}\\n\\n/**\\n * Fired before a tool executes. Can block.\\n *\\n * `event.input` is mutable. Mutate it in place to patch tool arguments before execution.\\n * Later `tool_call` handlers see earlier mutations. No re-validation is performed after mutation.\\n */\\nexport type ToolCallEvent =\\n\\t| BashToolCallEvent\\n\\t| ReadToolCallEvent\\n\\t| EditToolCallEvent\\n\\t| WriteToolCallEvent\\n\\t| GrepToolCallEvent\\n\\t| FindToolCallEvent\\n\\t| LsToolCallEvent\\n\\t| CustomToolCallEvent;\\n\\ninterface ToolResultEventBase {\\n\\ttype: \\\"tool_result\\\";\\n\\ttoolCallId: string;\\n\\tinput: Record<string, unknown>;\\n\\tcontent: (TextContent | ImageContent)[];\\n\\tisError: boolean;\\n}\\n\\nexport interface BashToolResultEvent extends ToolResultEventBase {\\n\\ttoolName: \\\"bash\\\";\\n\\tdetails: BashToolDetails | undefined;\\n}\\n\\nexport interface ReadToolResultEvent extends ToolResultEventBase {\\n\\ttoolName: \\\"read\\\";\\n\\tdetails: ReadToolDetails | undefined;\\n}\\n\\nexport interface EditToolResultEvent extends ToolResultEventBase {\\n\\ttoolName: \\\"edit\\\";\\n\\tdetails: EditToolDetails | undefined;\\n}\\n\\nexport interface WriteToolResultEvent extends ToolResultEventBase {\\n\\ttoolName: \\\"write\\\";\\n\\tdetails: undefined;\\n}\\n\\nexport interface GrepToolResultEvent extends ToolResultEventBase {\\n\\ttoolName: \\\"grep\\\";\\n\\tdetails: GrepToolDetails | undefined;\\n}\\n\\nexport interface FindToolResultEvent extends ToolResultEventBase {\\n\\ttoolName: \\\"find\\\";\\n\\tdetails: FindToolDetails | undefined;\\n}\\n\\nexport interface LsToolResultEvent extends ToolResultEventBase {\\n\\ttoolName: \\\"ls\\\";\\n\\tdetails: LsToolDetails | undefined;\\n}\\n\\nexport interface CustomToolResultEvent extends ToolResultEventBase {\\n\\ttoolName: string;\\n\\tdetails: unknown;\\n}\\n\\n/** Fired after a tool executes. Can modify result. */\\nexport type ToolResultEvent =\\n\\t| BashToolResultEvent\\n\\t| ReadToolResultEvent\\n\\t| EditToolResultEvent\\n\\t| WriteToolResultEvent\\n\\t| GrepToolResultEvent\\n\\t| FindToolResultEvent\\n\\t| LsToolResultEvent\\n\\t| CustomToolResultEvent;\\n\\n// Type guards for ToolResultEvent\\nexport function isBashToolResult(e: ToolResultEvent): e is BashToolResultEvent {\\n\\treturn e.toolName === \\\"bash\\\";\\n}\\nexport function isReadToolResult(e: ToolResultEvent): e is ReadToolResultEvent {\\n\\treturn e.toolName === \\\"read\\\";\\n}\\nexport function isEditToolResult(e: ToolResultEvent): e is EditToolResultEvent {\\n\\treturn e.toolName === \\\"edit\\\";\\n}\\nexport function isWriteToolResult(e: ToolResultEvent): e is WriteToolResultEvent {\\n\\treturn e.toolName === \\\"write\\\";\\n}\\nexport function isGrepToolResult(e: ToolResultEvent): e is GrepToolResultEvent {\\n\\treturn e.toolName === \\\"grep\\\";\\n}\\nexport function isFindToolResult(e: ToolResultEvent): e is FindToolResultEvent {\\n\\treturn e.toolName === \\\"find\\\";\\n}\\nexport function isLsToolResult(e: ToolResultEvent): e is LsToolResultEvent {\\n\\treturn e.toolName === \\\"ls\\\";\\n}\\n\\n/**\\n * Type guard for narrowing ToolCallEvent by tool name.\\n *\\n * Built-in tools narrow automatically (no type params needed):\\n * ```ts\\n * if (isToolCallEventType(\\\"bash\\\", event)) {\\n *   event.input.command;  // string\\n * }\\n * ```\\n *\\n * Custom tools require explicit type parameters:\\n * ```ts\\n * if (isToolCallEventType<\\\"my_tool\\\", MyToolInput>(\\\"my_tool\\\", event)) {\\n *   event.input.action;  // typed\\n * }\\n * ```\\n *\\n * Note: Direct narrowing via `event.toolName === \\\"bash\\\"` doesn't work because\\n * CustomToolCallEvent.toolName is `string` which overlaps with all literals.\\n */\\nexport function isToolCallEventType(toolName: \\\"bash\\\", event: ToolCallEvent): event is BashToolCallEvent;\\nexport function isToolCallEventType(toolName: \\\"read\\\", event: ToolCallEvent): event is ReadToolCallEvent;\\nexport function isToolCallEventType(toolName: \\\"edit\\\", event: ToolCallEvent): event is EditToolCallEvent;\\nexport function isToolCallEventType(toolName: \\\"write\\\", event: ToolCallEvent): event is WriteToolCallEvent;\\nexport function isToolCallEventType(toolName: \\\"grep\\\", event: ToolCallEvent): event is GrepToolCallEvent;\\nexport function isToolCallEventType(toolName: \\\"find\\\", event: ToolCallEvent): event is FindToolCallEvent;\\nexport function isToolCallEventType(toolName: \\\"ls\\\", event: ToolCallEvent): event is LsToolCallEvent;\\nexport function isToolCallEventType<TName extends string, TInput extends Record<string, unknown>>(\\n\\ttoolName: TName,\\n\\tevent: ToolCallEvent,\\n): event is ToolCallEvent & { toolName: TName; input: TInput };\\nexport function isToolCallEventType(toolName: string, event: ToolCallEvent): boolean {\\n\\treturn event.toolName === toolName;\\n}\\n\\n/** Union of all event types */\\nexport type ExtensionEvent =\\n\\t| ProjectTrustEvent\\n\\t| ResourcesDiscoverEvent\\n\\t| SessionEvent\\n\\t| ContextEvent\\n\\t| BeforeProviderRequestEvent\\n\\t| AfterProviderResponseEvent\\n\\t| BeforeAgentStartEvent\\n\\t| AgentStartEvent\\n\\t| AgentEndEvent\\n\\t| TurnStartEvent\\n\\t| TurnEndEvent\\n\\t| MessageStartEvent\\n\\t| MessageUpdateEvent\\n\\t| MessageEndEvent\\n\\t| ToolExecutionStartEvent\\n\\t| ToolExecutionUpdateEvent\\n\\t| ToolExecutionEndEvent\\n\\t| ModelSelectEvent\\n\\t| ThinkingLevelSelectEvent\\n\\t| UserBashEvent\\n\\t| InputEvent\\n\\t| ToolCallEvent\\n\\t| ToolResultEvent;\\n\\n// ============================================================================\\n// Event Results\\n// ============================================================================\\n\\nexport interface ContextEventResult {\\n\\tmessages?: AgentMessage[];\\n}\\n\\nexport type BeforeProviderRequestEventResult = unknown;\\n\\nexport interface ToolCallEventResult {\\n\\t/** Block tool execution. To modify arguments, mutate `event.input` in place instead. */\\n\\tblock?: boolean;\\n\\treason?: string;\\n}\\n\\n/** Result from user_bash event handler */\\nexport interface UserBashEventResult {\\n\\t/** Custom operations to use for execution */\\n\\toperations?: BashOperations;\\n\\t/** Full replacement: extension handled execution, use this result */\\n\\tresult?: BashResult;\\n}\\n\\nexport interface ToolResultEventResult {\\n\\tcontent?: (TextContent | ImageContent)[];\\n\\tdetails?: unknown;\\n\\tisError?: boolean;\\n}\\n\\nexport interface MessageEndEventResult {\\n\\t/** Replace the finalized message. The replacement must keep the original message role. */\\n\\tmessage?: AgentMessage;\\n}\\n\\nexport interface BeforeAgentStartEventResult {\\n\\tmessage?: Pick<CustomMessage, \\\"customType\\\" | \\\"content\\\" | \\\"display\\\" | \\\"details\\\">;\\n\\t/** Replace the system prompt for this turn. If multiple extensions return this, they are chained. */\\n\\tsystemPrompt?: string;\\n}\\n\\nexport interface SessionBeforeSwitchResult {\\n\\tcancel?: boolean;\\n}\\n\\nexport interface SessionBeforeForkResult {\\n\\tcancel?: boolean;\\n\\tskipConversationRestore?: boolean;\\n}\\n\\nexport interface SessionBeforeCompactResult {\\n\\tcancel?: boolean;\\n\\tcompaction?: CompactionResult;\\n}\\n\\nexport interface SessionBeforeTreeResult {\\n\\tcancel?: boolean;\\n\\tsummary?: {\\n\\t\\tsummary: string;\\n\\t\\tdetails?: unknown;\\n\\t};\\n\\t/** Override custom instructions for summarization */\\n\\tcustomInstructions?: string;\\n\\t/** Override whether customInstructions replaces the default prompt */\\n\\treplaceInstructions?: boolean;\\n\\t/** Override label to attach to the branch summary entry */\\n\\tlabel?: string;\\n}\\n\\n// ============================================================================\\n// Message Rendering\\n// ============================================================================\\n\\nexport interface MessageRenderOptions {\\n\\texpanded: boolean;\\n}\\n\\nexport type MessageRenderer<T = unknown> = (\\n\\tmessage: CustomMessage<T>,\\n\\toptions: MessageRenderOptions,\\n\\ttheme: Theme,\\n) => Component | undefined;\\n\\n// ============================================================================\\n// Command Registration\\n// ============================================================================\\n\\nexport interface RegisteredCommand {\\n\\tname: string;\\n\\tsourceInfo: SourceInfo;\\n\\tdescription?: string;\\n\\tgetArgumentCompletions?: (argumentPrefix: string) => AutocompleteItem[] | null | Promise<AutocompleteItem[] | null>;\\n\\thandler: (args: string, ctx: ExtensionCommandContext) => Promise<void>;\\n}\\n\\nexport interface ResolvedCommand extends RegisteredCommand {\\n\\tinvocationName: string;\\n}\\n\\n// ============================================================================\\n// Extension API\\n// ============================================================================\\n\\n/** Handler function type for events */\\n// biome-ignore lint/suspicious/noConfusingVoidType: void allows bare return statements\\nexport type ExtensionHandler<E, R = undefined> = (event: E, ctx: ExtensionContext) => Promise<R | void> | R | void;\\n\\n/**\\n * ExtensionAPI passed to extension factory functions.\\n */\\nexport interface ExtensionAPI {\\n\\t// =========================================================================\\n\\t// Event Subscription\\n\\t// =========================================================================\\n\\n\\ton(event: \\\"project_trust\\\", handler: ProjectTrustHandler): void;\\n\\ton(event: \\\"resources_discover\\\", handler: ExtensionHandler<ResourcesDiscoverEvent, ResourcesDiscoverResult>): void;\\n\\ton(event: \\\"session_start\\\", handler: ExtensionHandler<SessionStartEvent>): void;\\n\\ton(\\n\\t\\tevent: \\\"session_before_switch\\\",\\n\\t\\thandler: ExtensionHandler<SessionBeforeSwitchEvent, SessionBeforeSwitchResult>,\\n\\t): void;\\n\\ton(event: \\\"session_before_fork\\\", handler: ExtensionHandler<SessionBeforeForkEvent, SessionBeforeForkResult>): void;\\n\\ton(\\n\\t\\tevent: \\\"session_before_compact\\\",\\n\\t\\thandler: ExtensionHandler<SessionBeforeCompactEvent, SessionBeforeCompactResult>,\\n\\t): void;\\n\\ton(event: \\\"session_compact\\\", handler: ExtensionHandler<SessionCompactEvent>): void;\\n\\ton(event: \\\"session_shutdown\\\", handler: ExtensionHandler<SessionShutdownEvent>): void;\\n\\ton(event: \\\"session_before_tree\\\", handler: ExtensionHandler<SessionBeforeTreeEvent, SessionBeforeTreeResult>): void;\\n\\ton(event: \\\"session_tree\\\", handler: ExtensionHandler<SessionTreeEvent>): void;\\n\\ton(event: \\\"context\\\", handler: ExtensionHandler<ContextEvent, ContextEventResult>): void;\\n\\ton(\\n\\t\\tevent: \\\"before_provider_request\\\",\\n\\t\\thandler: ExtensionHandler<BeforeProviderRequestEvent, BeforeProviderRequestEventResult>,\\n\\t): void;\\n\\ton(event: \\\"after_provider_response\\\", handler: ExtensionHandler<AfterProviderResponseEvent>): void;\\n\\ton(event: \\\"before_agent_start\\\", handler: ExtensionHandler<BeforeAgentStartEvent, BeforeAgentStartEventResult>): void;\\n\\ton(event: \\\"agent_start\\\", handler: ExtensionHandler<AgentStartEvent>): void;\\n\\ton(event: \\\"agent_end\\\", handler: ExtensionHandler<AgentEndEvent>): void;\\n\\ton(event: \\\"turn_start\\\", handler: ExtensionHandler<TurnStartEvent>): void;\\n\\ton(event: \\\"turn_end\\\", handler: ExtensionHandler<TurnEndEvent>): void;\\n\\ton(event: \\\"message_start\\\", handler: ExtensionHandler<MessageStartEvent>): void;\\n\\ton(event: \\\"message_update\\\", handler: ExtensionHandler<MessageUpdateEvent>): void;\\n\\ton(event: \\\"message_end\\\", handler: ExtensionHandler<MessageEndEvent, MessageEndEventResult>): void;\\n\\ton(event: \\\"tool_execution_start\\\", handler: ExtensionHandler<ToolExecutionStartEvent>): void;\\n\\ton(event: \\\"tool_execution_update\\\", handler: ExtensionHandler<ToolExecutionUpdateEvent>): void;\\n\\ton(event: \\\"tool_execution_end\\\", handler: ExtensionHandler<ToolExecutionEndEvent>): void;\\n\\ton(event: \\\"model_select\\\", handler: ExtensionHandler<ModelSelectEvent>): void;\\n\\ton(event: \\\"thinking_level_select\\\", handler: ExtensionHandler<ThinkingLevelSelectEvent>): void;\\n\\ton(event: \\\"tool_call\\\", handler: ExtensionHandler<ToolCallEvent, ToolCallEventResult>): void;\\n\\ton(event: \\\"tool_result\\\", handler: ExtensionHandler<ToolResultEvent, ToolResultEventResult>): void;\\n\\ton(event: \\\"user_bash\\\", handler: ExtensionHandler<UserBashEvent, UserBashEventResult>): void;\\n\\ton(event: \\\"input\\\", handler: ExtensionHandler<InputEvent, InputEventResult>): void;\\n\\n\\t// =========================================================================\\n\\t// Tool Registration\\n\\t// =========================================================================\\n\\n\\t/** Register a tool that the LLM can call. */\\n\\tregisterTool<TParams extends TSchema = TSchema, TDetails = unknown, TState = any>(\\n\\t\\ttool: ToolDefinition<TParams, TDetails, TState>,\\n\\t): void;\\n\\n\\t// =========================================================================\\n\\t// Command, Shortcut, Flag Registration\\n\\t// =========================================================================\\n\\n\\t/** Register a custom command. */\\n\\tregisterCommand(name: string, options: Omit<RegisteredCommand, \\\"name\\\" | \\\"sourceInfo\\\">): void;\\n\\n\\t/** Register a keyboard shortcut. */\\n\\tregisterShortcut(\\n\\t\\tshortcut: KeyId,\\n\\t\\toptions: {\\n\\t\\t\\tdescription?: string;\\n\\t\\t\\thandler: (ctx: ExtensionContext) => Promise<void> | void;\\n\\t\\t},\\n\\t): void;\\n\\n\\t/** Register a CLI flag. */\\n\\tregisterFlag(\\n\\t\\tname: string,\\n\\t\\toptions: {\\n\\t\\t\\tdescription?: string;\\n\\t\\t\\ttype: \\\"boolean\\\" | \\\"string\\\";\\n\\t\\t\\tdefault?: boolean | string;\\n\\t\\t},\\n\\t): void;\\n\\n\\t/** Get the value of a registered CLI flag. */\\n\\tgetFlag(name: string): boolean | string | undefined;\\n\\n\\t// =========================================================================\\n\\t// Message Rendering\\n\\t// =========================================================================\\n\\n\\t/** Register a custom renderer for CustomMessageEntry. */\\n\\tregisterMessageRenderer<T = unknown>(customType: string, renderer: MessageRenderer<T>): void;\\n\\n\\t// =========================================================================\\n\\t// Actions\\n\\t// =========================================================================\\n\\n\\t/** Send a custom message to the session. */\\n\\tsendMessage<T = unknown>(\\n\\t\\tmessage: Pick<CustomMessage<T>, \\\"customType\\\" | \\\"content\\\" | \\\"display\\\" | \\\"details\\\">,\\n\\t\\toptions?: { triggerTurn?: boolean; deliverAs?: \\\"steer\\\" | \\\"followUp\\\" | \\\"nextTurn\\\" },\\n\\t): void;\\n\\n\\t/**\\n\\t * Send a user message to the agent. Always triggers a turn.\\n\\t * When the agent is streaming, use deliverAs to specify how to queue the message.\\n\\t */\\n\\tsendUserMessage(\\n\\t\\tcontent: string | (TextContent | ImageContent)[],\\n\\t\\toptions?: { deliverAs?: \\\"steer\\\" | \\\"followUp\\\" },\\n\\t): void;\\n\\n\\t/** Append a custom entry to the session for state persistence (not sent to LLM). */\\n\\tappendEntry<T = unknown>(customType: string, data?: T): void;\\n\\n\\t// =========================================================================\\n\\t// Session Metadata\\n\\t// =========================================================================\\n\\n\\t/** Set the session display name (shown in session selector). */\\n\\tsetSessionName(name: string): void;\\n\\n\\t/** Get the current session name, if set. */\\n\\tgetSessionName(): string | undefined;\\n\\n\\t/** Set or clear a label on an entry. Labels are user-defined markers for bookmarking/navigation. */\\n\\tsetLabel(entryId: string, label: string | undefined): void;\\n\\n\\t/** Execute a shell command. */\\n\\texec(command: string, args: string[], options?: ExecOptions): Promise<ExecResult>;\\n\\n\\t/** Get the list of currently active tool names. */\\n\\tgetActiveTools(): string[];\\n\\n\\t/** Get all configured tools with parameter schema, prompt guidelines, and source metadata. */\\n\\tgetAllTools(): ToolInfo[];\\n\\n\\t/** Set the active tools by name. */\\n\\tsetActiveTools(toolNames: string[]): void;\\n\\n\\t/** Get available slash commands in the current session. */\\n\\tgetCommands(): SlashCommandInfo[];\\n\\n\\t// =========================================================================\\n\\t// Model and Thinking Level\\n\\t// =========================================================================\\n\\n\\t/** Set the current model. Returns false if no API key available. */\\n\\tsetModel(model: Model<any>): Promise<boolean>;\\n\\n\\t/** Get current thinking level. */\\n\\tgetThinkingLevel(): ThinkingLevel;\\n\\n\\t/** Set thinking level (clamped to model capabilities). */\\n\\tsetThinkingLevel(level: ThinkingLevel): void;\\n\\n\\t// =========================================================================\\n\\t// Provider Registration\\n\\t// =========================================================================\\n\\n\\t/**\\n\\t * Register or override a model provider.\\n\\t *\\n\\t * If `models` is provided: replaces all existing models for this provider.\\n\\t * If only `baseUrl` is provided: overrides the URL for existing models.\\n\\t * If `oauth` is provided: registers OAuth provider for /login support.\\n\\t * If `streamSimple` is provided: registers a custom API stream handler.\\n\\t *\\n\\t * During initial extension load this call is queued and applied once the\\n\\t * runner has bound its context. After that it takes effect immediately, so\\n\\t * it is safe to call from command handlers or event callbacks without\\n\\t * requiring a `/reload`.\\n\\t *\\n\\t * @example\\n\\t * // Register a new provider with custom models\\n\\t * pi.registerProvider(\\\"my-proxy\\\", {\\n\\t *   baseUrl: \\\"https://proxy.example.com\\\",\\n\\t *   apiKey: \\\"$PROXY_API_KEY\\\",\\n\\t *   api: \\\"anthropic-messages\\\",\\n\\t *   models: [\\n\\t *     {\\n\\t *       id: \\\"claude-sonnet-4-20250514\\\",\\n\\t *       name: \\\"Claude 4 Sonnet (proxy)\\\",\\n\\t *       reasoning: false,\\n\\t *       input: [\\\"text\\\", \\\"image\\\"],\\n\\t *       cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },\\n\\t *       contextWindow: 200000,\\n\\t *       maxTokens: 16384\\n\\t *     }\\n\\t *   ]\\n\\t * });\\n\\t *\\n\\t * @example\\n\\t * // Override baseUrl for an existing provider\\n\\t * pi.registerProvider(\\\"anthropic\\\", {\\n\\t *   baseUrl: \\\"https://proxy.example.com\\\"\\n\\t * });\\n\\t *\\n\\t * @example\\n\\t * // Register provider with OAuth support\\n\\t * pi.registerProvider(\\\"corporate-ai\\\", {\\n\\t *   baseUrl: \\\"https://ai.corp.com\\\",\\n\\t *   api: \\\"openai-responses\\\",\\n\\t *   models: [...],\\n\\t *   oauth: {\\n\\t *     name: \\\"Corporate AI (SSO)\\\",\\n\\t *     async login(callbacks) { ... },\\n\\t *     async refreshToken(credentials) { ... },\\n\\t *     getApiKey(credentials) { return credentials.access; }\\n\\t *   }\\n\\t * });\\n\\t */\\n\\tregisterProvider(name: string, config: ProviderConfig): void;\\n\\n\\t/**\\n\\t * Unregister a previously registered provider.\\n\\t *\\n\\t * Removes all models belonging to the named provider and restores any\\n\\t * built-in models that were overridden by it. Has no effect if the provider\\n\\t * is not currently registered.\\n\\t *\\n\\t * Like `registerProvider`, this takes effect immediately when called after\\n\\t * the initial load phase.\\n\\t *\\n\\t * @example\\n\\t * pi.unregisterProvider(\\\"my-proxy\\\");\\n\\t */\\n\\tunregisterProvider(name: string): void;\\n\\n\\t/** Shared event bus for extension communication. */\\n\\tevents: EventBus;\\n}\\n\\n// ============================================================================\\n// Provider Registration Types\\n// ============================================================================\\n\\n/** Configuration for registering a provider via pi.registerProvider(). */\\nexport interface ProviderConfig {\\n\\t/** Display name for the provider in UI. */\\n\\tname?: string;\\n\\t/** Base URL for the API endpoint. Required when defining models. */\\n\\tbaseUrl?: string;\\n\\t/** API key literal, env interpolation ($ENV_VAR or ${ENV_VAR}), or leading !command. Required when defining models (unless oauth provided). */\\n\\tapiKey?: string;\\n\\t/** API type. Required at provider or model level when defining models. */\\n\\tapi?: Api;\\n\\t/** Optional streamSimple handler for custom APIs. */\\n\\tstreamSimple?: (model: Model<Api>, context: Context, options?: SimpleStreamOptions) => AssistantMessageEventStream;\\n\\t/** Custom headers to include in requests. */\\n\\theaders?: Record<string, string>;\\n\\t/** If true, adds Authorization: Bearer header with the resolved API key. */\\n\\tauthHeader?: boolean;\\n\\t/** Models to register. If provided, replaces all existing models for this provider. */\\n\\tmodels?: ProviderModelConfig[];\\n\\t/** OAuth provider for /login support. The `id` is set automatically from the provider name. */\\n\\toauth?: {\\n\\t\\t/** Display name for the provider in login UI. */\\n\\t\\tname: string;\\n\\t\\t/** Run the login flow, return credentials to persist. */\\n\\t\\tlogin(callbacks: OAuthLoginCallbacks): Promise<OAuthCredentials>;\\n\\t\\t/** Refresh expired credentials, return updated credentials to persist. */\\n\\t\\trefreshToken(credentials: OAuthCredentials): Promise<OAuthCredentials>;\\n\\t\\t/** Convert credentials to API key string for the provider. */\\n\\t\\tgetApiKey(credentials: OAuthCredentials): string;\\n\\t\\t/** Optional: modify models for this provider (e.g., update baseUrl based on credentials). */\\n\\t\\tmodifyModels?(models: Model<Api>[], credentials: OAuthCredentials): Model<Api>[];\\n\\t};\\n}\\n\\n/** Configuration for a model within a provider. */\\nexport interface ProviderModelConfig {\\n\\t/** Model ID (e.g., \\\"claude-sonnet-4-20250514\\\"). */\\n\\tid: string;\\n\\t/** Display name (e.g., \\\"Claude 4 Sonnet\\\"). */\\n\\tname: string;\\n\\t/** API type override for this model. */\\n\\tapi?: Api;\\n\\t/** API endpoint URL override for this model. */\\n\\tbaseUrl?: string;\\n\\t/** Whether the model supports extended thinking. */\\n\\treasoning: boolean;\\n\\t/** Maps pi thinking levels to provider/model-specific values; null marks a level unsupported. */\\n\\tthinkingLevelMap?: Model<Api>[\\\"thinkingLevelMap\\\"];\\n\\t/** Supported input types. */\\n\\tinput: (\\\"text\\\" | \\\"image\\\")[];\\n\\t/** Cost per token (for tracking, can be 0). */\\n\\tcost: { input: number; output: number; cacheRead: number; cacheWrite: number };\\n\\t/** Maximum context window size in tokens. */\\n\\tcontextWindow: number;\\n\\t/** Maximum output tokens. */\\n\\tmaxTokens: number;\\n\\t/** Custom headers for this model. */\\n\\theaders?: Record<string, string>;\\n\\t/** OpenAI compatibility settings. */\\n\\tcompat?: Model<Api>[\\\"compat\\\"];\\n}\\n\\n/** Extension factory function type. Supports both sync and async initialization. */\\nexport type ExtensionFactory = (pi: ExtensionAPI) => void | Promise<void>;\\n\\n// ============================================================================\\n// Loaded Extension Types\\n// ============================================================================\\n\\nexport interface RegisteredTool {\\n\\tdefinition: ToolDefinition;\\n\\tsourceInfo: SourceInfo;\\n}\\n\\nexport interface ExtensionFlag {\\n\\tname: string;\\n\\tdescription?: string;\\n\\ttype: \\\"boolean\\\" | \\\"string\\\";\\n\\tdefault?: boolean | string;\\n\\textensionPath: string;\\n}\\n\\nexport interface ExtensionShortcut {\\n\\tshortcut: KeyId;\\n\\tdescription?: string;\\n\\thandler: (ctx: ExtensionContext) => Promise<void> | void;\\n\\textensionPath: string;\\n}\\n\\ntype HandlerFn = (...args: unknown[]) => Promise<unknown>;\\n\\nexport type SendMessageHandler = <T = unknown>(\\n\\tmessage: Pick<CustomMessage<T>, \\\"customType\\\" | \\\"content\\\" | \\\"display\\\" | \\\"details\\\">,\\n\\toptions?: { triggerTurn?: boolean; deliverAs?: \\\"steer\\\" | \\\"followUp\\\" | \\\"nextTurn\\\" },\\n) => void;\\n\\nexport type SendUserMessageHandler = (\\n\\tcontent: string | (TextContent | ImageContent)[],\\n\\toptions?: { deliverAs?: \\\"steer\\\" | \\\"followUp\\\" },\\n) => void;\\n\\nexport type AppendEntryHandler = <T = unknown>(customType: string, data?: T) => void;\\n\\nexport type SetSessionNameHandler = (name: string) => void;\\n\\nexport type GetSessionNameHandler = () => string | undefined;\\n\\nexport type GetActiveToolsHandler = () => string[];\\n\\n/** Tool info with name, description, parameter schema, prompt guidelines, and source metadata. */\\nexport type ToolInfo = Pick<ToolDefinition, \\\"name\\\" | \\\"description\\\" | \\\"parameters\\\" | \\\"promptGuidelines\\\"> & {\\n\\tsourceInfo: SourceInfo;\\n};\\n\\nexport type GetAllToolsHandler = () => ToolInfo[];\\n\\nexport type GetCommandsHandler = () => SlashCommandInfo[];\\n\\nexport type SetActiveToolsHandler = (toolNames: string[]) => void;\\n\\nexport type RefreshToolsHandler = () => void;\\n\\nexport type SetModelHandler = (model: Model<any>) => Promise<boolean>;\\n\\nexport type GetThinkingLevelHandler = () => ThinkingLevel;\\n\\nexport type SetThinkingLevelHandler = (level: ThinkingLevel) => void;\\n\\nexport type SetLabelHandler = (entryId: string, label: string | undefined) => void;\\n\\n/**\\n * Shared state created by loader, used during registration and runtime.\\n * Contains flag values (defaults set during registration, CLI values set after).\\n */\\nexport interface ExtensionRuntimeState {\\n\\tflagValues: Map<string, boolean | string>;\\n\\t/** Provider registrations queued during extension loading, processed when runner binds */\\n\\tpendingProviderRegistrations: Array<{ name: string; config: ProviderConfig; extensionPath: string }>;\\n\\t/** Throws when this extension instance is stale after runtime replacement. */\\n\\tassertActive: () => void;\\n\\t/** Marks this extension instance as stale after runtime replacement or reload. */\\n\\tinvalidate: (message?: string) => void;\\n\\t/**\\n\\t * Register or unregister a provider.\\n\\t *\\n\\t * Before bindCore(): queues registrations / removes from queue.\\n\\t * After bindCore(): calls ModelRegistry directly for immediate effect.\\n\\t */\\n\\tregisterProvider: (name: string, config: ProviderConfig, extensionPath?: string) => void;\\n\\tunregisterProvider: (name: string, extensionPath?: string) => void;\\n}\\n\\n/**\\n * Action implementations for pi.* API methods.\\n * Provided to runner.initialize(), copied into the shared runtime.\\n */\\nexport interface ExtensionActions {\\n\\tsendMessage: SendMessageHandler;\\n\\tsendUserMessage: SendUserMessageHandler;\\n\\tappendEntry: AppendEntryHandler;\\n\\tsetSessionName: SetSessionNameHandler;\\n\\tgetSessionName: GetSessionNameHandler;\\n\\tsetLabel: SetLabelHandler;\\n\\tgetActiveTools: GetActiveToolsHandler;\\n\\tgetAllTools: GetAllToolsHandler;\\n\\tsetActiveTools: SetActiveToolsHandler;\\n\\trefreshTools: RefreshToolsHandler;\\n\\tgetCommands: GetCommandsHandler;\\n\\tsetModel: SetModelHandler;\\n\\tgetThinkingLevel: GetThinkingLevelHandler;\\n\\tsetThinkingLevel: SetThinkingLevelHandler;\\n}\\n\\n/**\\n * Actions for ExtensionContext (ctx.* in event handlers).\\n * Required by all modes.\\n */\\nexport interface ExtensionContextActions {\\n\\tgetModel: () => Model<any> | undefined;\\n\\tisIdle: () => boolean;\\n\\tgetSignal: () => AbortSignal | undefined;\\n\\tabort: () => void;\\n\\thasPendingMessages: () => boolean;\\n\\tshutdown: () => void;\\n\\tgetContextUsage: () => ContextUsage | undefined;\\n\\tcompact: (options?: CompactOptions) => void;\\n\\tgetSystemPrompt: () => string;\\n\\tgetSystemPromptOptions?: () => BuildSystemPromptOptions;\\n}\\n\\n/**\\n * Actions for ExtensionCommandContext (ctx.* in command handlers).\\n * Only needed for interactive mode where extension commands are invokable.\\n */\\nexport interface ExtensionCommandContextActions {\\n\\twaitForIdle: () => Promise<void>;\\n\\tnewSession: (options?: {\\n\\t\\tparentSession?: string;\\n\\t\\tsetup?: (sessionManager: SessionManager) => Promise<void>;\\n\\t\\twithSession?: (ctx: ReplacedSessionContext) => Promise<void>;\\n\\t}) => Promise<{ cancelled: boolean }>;\\n\\tfork: (\\n\\t\\tentryId: string,\\n\\t\\toptions?: { position?: \\\"before\\\" | \\\"at\\\"; withSession?: (ctx: ReplacedSessionContext) => Promise<void> },\\n\\t) => Promise<{ cancelled: boolean }>;\\n\\tnavigateTree: (\\n\\t\\ttargetId: string,\\n\\t\\toptions?: { summarize?: boolean; customInstructions?: string; replaceInstructions?: boolean; label?: string },\\n\\t) => Promise<{ cancelled: boolean }>;\\n\\tswitchSession: (\\n\\t\\tsessionPath: string,\\n\\t\\toptions?: { withSession?: (ctx: ReplacedSessionContext) => Promise<void> },\\n\\t) => Promise<{ cancelled: boolean }>;\\n\\treload: () => Promise<void>;\\n}\\n\\n/**\\n * Full runtime = state + actions.\\n * Created by loader with throwing action stubs, completed by runner.initialize().\\n */\\nexport interface ExtensionRuntime extends ExtensionRuntimeState, ExtensionActions {}\\n\\n/** Loaded extension with all registered items. */\\nexport interface Extension {\\n\\tpath: string;\\n\\tresolvedPath: string;\\n\\tsourceInfo: SourceInfo;\\n\\thandlers: Map<string, HandlerFn[]>;\\n\\ttools: Map<string, RegisteredTool>;\\n\\tmessageRenderers: Map<string, MessageRenderer>;\\n\\tcommands: Map<string, RegisteredCommand>;\\n\\tflags: Map<string, ExtensionFlag>;\\n\\tshortcuts: Map<KeyId, ExtensionShortcut>;\\n}\\n\\n/** Result of loading extensions. */\\nexport interface LoadExtensionsResult {\\n\\textensions: Extension[];\\n\\terrors: Array<{ path: string; error: string }>;\\n\\t/** Shared runtime - actions are throwing stubs until runner.initialize() */\\n\\truntime: ExtensionRuntime;\\n}\\n\\n// ============================================================================\\n// Extension Error\\n// ============================================================================\\n\\nexport interface ExtensionError {\\n\\textensionPath: string;\\n\\tevent: string;\\n\\terror: string;\\n\\tstack?: string;\\n}\\n\",\"upstream/pi-mono/packages/coding-agent/docs/extensions.md\":\"> pi can create extensions. Ask it to build one for your use case.\\n\\n# Extensions\\n\\nExtensions are TypeScript modules that extend pi's behavior. They can subscribe to lifecycle events, register custom tools callable by the LLM, add commands, and more.\\n\\n> **Placement for /reload:** Put extensions in `~/.pi/agent/extensions/` (global) or `.pi/extensions/` (project-local) for auto-discovery. Use `pi -e ./path.ts` only for quick tests. Extensions in auto-discovered locations can be hot-reloaded with `/reload`.\\n\\n**Key capabilities:**\\n- **Custom tools** - Register tools the LLM can call via `pi.registerTool()`\\n- **Event interception** - Block or modify tool calls, inject context, customize compaction\\n- **User interaction** - Prompt users via `ctx.ui` (select, confirm, input, notify)\\n- **Custom UI components** - Full TUI components with keyboard input via `ctx.ui.custom()` for complex interactions\\n- **Custom commands** - Register commands like `/mycommand` via `pi.registerCommand()`\\n- **Session persistence** - Store state that survives restarts via `pi.appendEntry()`\\n- **Custom rendering** - Control how tool calls/results and messages appear in TUI\\n\\n**Example use cases:**\\n- Permission gates (confirm before `rm -rf`, `sudo`, etc.)\\n- Git checkpointing (stash at each turn, restore on branch)\\n- Path protection (block writes to `.env`, `node_modules/`)\\n- Custom compaction (summarize conversation your way)\\n- Conversation summaries (see `summarize.ts` example)\\n- Interactive tools (questions, wizards, custom dialogs)\\n- Stateful tools (todo lists, connection pools)\\n- External integrations (file watchers, webhooks, CI triggers)\\n- Games while you wait (see `snake.ts` example)\\n\\nSee [examples/extensions/](../examples/extensions/) for working implementations.\\n\\n## Table of Contents\\n\\n- [Quick Start](#quick-start)\\n- [Extension Locations](#extension-locations)\\n- [Available Imports](#available-imports)\\n- [Writing an Extension](#writing-an-extension)\\n  - [Extension Styles](#extension-styles)\\n- [Events](#events)\\n  - [Lifecycle Overview](#lifecycle-overview)\\n  - [Resource Events](#resource-events)\\n  - [Session Events](#session-events)\\n  - [Agent Events](#agent-events)\\n  - [Model Events](#model-events)\\n  - [Tool Events](#tool-events)\\n- [ExtensionContext](#extensioncontext)\\n- [ExtensionCommandContext](#extensioncommandcontext)\\n- [ExtensionAPI Methods](#extensionapi-methods)\\n- [State Management](#state-management)\\n- [Custom Tools](#custom-tools)\\n- [Custom UI](#custom-ui)\\n- [Error Handling](#error-handling)\\n- [Mode Behavior](#mode-behavior)\\n- [Examples Reference](#examples-reference)\\n\\n## Quick Start\\n\\nCreate `~/.pi/agent/extensions/my-extension.ts`:\\n\\n```typescript\\nimport type { ExtensionAPI } from \\\"@earendil-works/pi-coding-agent\\\";\\nimport { Type } from \\\"typebox\\\";\\n\\nexport default function (pi: ExtensionAPI) {\\n  // React to events\\n  pi.on(\\\"session_start\\\", async (_event, ctx) => {\\n    ctx.ui.notify(\\\"Extension loaded!\\\", \\\"info\\\");\\n  });\\n\\n  pi.on(\\\"tool_call\\\", async (event, ctx) => {\\n    if (event.toolName === \\\"bash\\\" && event.input.command?.includes(\\\"rm -rf\\\")) {\\n      const ok = await ctx.ui.confirm(\\\"Dangerous!\\\", \\\"Allow rm -rf?\\\");\\n      if (!ok) return { block: true, reason: \\\"Blocked by user\\\" };\\n    }\\n  });\\n\\n  // Register a custom tool\\n  pi.registerTool({\\n    name: \\\"greet\\\",\\n    label: \\\"Greet\\\",\\n    description: \\\"Greet someone by name\\\",\\n    parameters: Type.Object({\\n      name: Type.String({ description: \\\"Name to greet\\\" }),\\n    }),\\n    async execute(toolCallId, params, signal, onUpdate, ctx) {\\n      return {\\n        content: [{ type: \\\"text\\\", text: `Hello, ${params.name}!` }],\\n        details: {},\\n      };\\n    },\\n  });\\n\\n  // Register a command\\n  pi.registerCommand(\\\"hello\\\", {\\n    description: \\\"Say hello\\\",\\n    handler: async (args, ctx) => {\\n      ctx.ui.notify(`Hello ${args || \\\"world\\\"}!`, \\\"info\\\");\\n    },\\n  });\\n}\\n```\\n\\nTest with `--extension` (or `-e`) flag:\\n\\n```bash\\npi -e ./my-extension.ts\\n```\\n\\n## Extension Locations\\n\\n> **Security:** Extensions run with your full system permissions and can execute arbitrary code. Only install from sources you trust.\\n\\nExtensions are auto-discovered from trusted locations. Project-local `.pi/extensions` entries load only after the project is trusted.\\n\\n| Location | Scope |\\n|----------|-------|\\n| `~/.pi/agent/extensions/*.ts` | Global (all projects) |\\n| `~/.pi/agent/extensions/*/index.ts` | Global (subdirectory) |\\n| `.pi/extensions/*.ts` | Project-local |\\n| `.pi/extensions/*/index.ts` | Project-local (subdirectory) |\\n\\nAdditional paths via `settings.json`:\\n\\n```json\\n{\\n  \\\"packages\\\": [\\n    \\\"npm:@foo/bar@1.0.0\\\",\\n    \\\"git:github.com/user/repo@v1\\\"\\n  ],\\n  \\\"extensions\\\": [\\n    \\\"/path/to/local/extension.ts\\\",\\n    \\\"/path/to/local/extension/dir\\\"\\n  ]\\n}\\n```\\n\\nTo share extensions via npm or git as pi packages, see [packages.md](packages.md).\\n\\n## Available Imports\\n\\n| Package | Purpose |\\n|---------|---------|\\n| `@earendil-works/pi-coding-agent` | Extension types (`ExtensionAPI`, `ExtensionContext`, events) |\\n| `typebox` | Schema definitions for tool parameters |\\n| `@earendil-works/pi-ai` | AI utilities (`StringEnum` for Google-compatible enums) |\\n| `@earendil-works/pi-tui` | TUI components for custom rendering |\\n\\nnpm dependencies work too. Add a `package.json` next to your extension (or in a parent directory), run `npm install`, and imports from `node_modules/` are resolved automatically.\\n\\nFor distributed pi packages installed with `pi install` (npm or git), runtime deps must be in `dependencies`. Package installation uses production installs (`npm install --omit=dev`) by default, so `devDependencies` are not available at runtime; when `npmCommand` is configured, git packages use plain `install` for compatibility with wrappers.\\n\\nNode.js built-ins (`node:fs`, `node:path`, etc.) are also available.\\n\\n## Writing an Extension\\n\\nAn extension exports a default factory function that receives `ExtensionAPI`. The factory can be synchronous or asynchronous:\\n\\n```typescript\\nimport type { ExtensionAPI } from \\\"@earendil-works/pi-coding-agent\\\";\\n\\nexport default function (pi: ExtensionAPI) {\\n  // Subscribe to events\\n  pi.on(\\\"event_name\\\", async (event, ctx) => {\\n    // ctx.ui for user interaction\\n    const ok = await ctx.ui.confirm(\\\"Title\\\", \\\"Are you sure?\\\");\\n    ctx.ui.notify(\\\"Done!\\\", \\\"info\\\");\\n    ctx.ui.setStatus(\\\"my-ext\\\", \\\"Processing...\\\");  // Footer status\\n    ctx.ui.setWidget(\\\"my-ext\\\", [\\\"Line 1\\\", \\\"Line 2\\\"]);  // Widget above editor (default)\\n  });\\n\\n  // Register tools, commands, shortcuts, flags\\n  pi.registerTool({ ... });\\n  pi.registerCommand(\\\"name\\\", { ... });\\n  pi.registerShortcut(\\\"ctrl+x\\\", { ... });\\n  pi.registerFlag(\\\"my-flag\\\", { ... });\\n}\\n```\\n\\nExtensions are loaded via [jiti](https://github.com/unjs/jiti), so TypeScript works without compilation.\\n\\nIf the factory returns a `Promise`, pi awaits it before continuing startup. That means async initialization completes before `session_start`, before `resources_discover`, and before provider registrations queued via `pi.registerProvider()` are flushed.\\n\\n### Async factory functions\\n\\nUse an async factory for one-time startup work such as fetching remote configuration or dynamically discovering available models.\\n\\n```typescript\\nimport type { ExtensionAPI } from \\\"@earendil-works/pi-coding-agent\\\";\\n\\nexport default async function (pi: ExtensionAPI) {\\n  const response = await fetch(\\\"http://localhost:1234/v1/models\\\");\\n  const payload = (await response.json()) as {\\n    data: Array<{\\n      id: string;\\n      name?: string;\\n      context_window?: number;\\n      max_tokens?: number;\\n    }>;\\n  };\\n\\n  pi.registerProvider(\\\"local-openai\\\", {\\n    baseUrl: \\\"http://localhost:1234/v1\\\",\\n    apiKey: \\\"$LOCAL_OPENAI_API_KEY\\\",\\n    api: \\\"openai-completions\\\",\\n    models: payload.data.map((model) => ({\\n      id: model.id,\\n      name: model.name ?? model.id,\\n      reasoning: false,\\n      input: [\\\"text\\\"],\\n      cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },\\n      contextWindow: model.context_window ?? 128000,\\n      maxTokens: model.max_tokens ?? 4096,\\n    })),\\n  });\\n}\\n```\\n\\nThis pattern makes the fetched models available during normal startup and to `pi --list-models`.\\n\\n### Extension Styles\\n\\n**Single file** - simplest, for small extensions:\\n\\n```\\n~/.pi/agent/extensions/\\n└── my-extension.ts\\n```\\n\\n**Directory with index.ts** - for multi-file extensions:\\n\\n```\\n~/.pi/agent/extensions/\\n└── my-extension/\\n    ├── index.ts        # Entry point (exports default function)\\n    ├── tools.ts        # Helper module\\n    └── utils.ts        # Helper module\\n```\\n\\n**Package with dependencies** - for extensions that need npm packages:\\n\\n```\\n~/.pi/agent/extensions/\\n└── my-extension/\\n    ├── package.json    # Declares dependencies and entry points\\n    ├── package-lock.json\\n    ├── node_modules/   # After npm install\\n    └── src/\\n        └── index.ts\\n```\\n\\n```json\\n// package.json\\n{\\n  \\\"name\\\": \\\"my-extension\\\",\\n  \\\"dependencies\\\": {\\n    \\\"zod\\\": \\\"^3.0.0\\\",\\n    \\\"chalk\\\": \\\"^5.0.0\\\"\\n  },\\n  \\\"pi\\\": {\\n    \\\"extensions\\\": [\\\"./src/index.ts\\\"]\\n  }\\n}\\n```\\n\\nRun `npm install` in the extension directory, then imports from `node_modules/` work automatically.\\n\\n## Events\\n\\n### Lifecycle Overview\\n\\n```\\npi starts\\n  │\\n  ├─► project_trust (user/global and CLI extensions only, before project resources load)\\n  ├─► session_start { reason: \\\"startup\\\" }\\n  └─► resources_discover { reason: \\\"startup\\\" }\\n      │\\n      ▼\\nuser sends prompt ─────────────────────────────────────────┐\\n  │                                                        │\\n  ├─► (extension commands checked first, bypass if found)  │\\n  ├─► input (can intercept, transform, or handle)          │\\n  ├─► (skill/template expansion if not handled)            │\\n  ├─► before_agent_start (can inject message, modify system prompt)\\n  ├─► agent_start                                          │\\n  ├─► message_start / message_update / message_end         │\\n  │                                                        │\\n  │   ┌─── turn (repeats while LLM calls tools) ───┐       │\\n  │   │                                            │       │\\n  │   ├─► turn_start                               │       │\\n  │   ├─► context (can modify messages)            │       │\\n  │   ├─► before_provider_request (can inspect or replace payload)\\n  │   ├─► after_provider_response (status + headers, before stream consume)\\n  │   │                                            │       │\\n  │   │   LLM responds, may call tools:            │       │\\n  │   │     ├─► tool_execution_start               │       │\\n  │   │     ├─► tool_call (can block)              │       │\\n  │   │     ├─► tool_execution_update              │       │\\n  │   │     ├─► tool_result (can modify)           │       │\\n  │   │     └─► tool_execution_end                 │       │\\n  │   │                                            │       │\\n  │   └─► turn_end                                 │       │\\n  │                                                        │\\n  └─► agent_end                                            │\\n                                                           │\\nuser sends another prompt ◄────────────────────────────────┘\\n\\n/new (new session) or /resume (switch session)\\n  ├─► session_before_switch (can cancel)\\n  ├─► session_shutdown\\n  ├─► session_start { reason: \\\"new\\\" | \\\"resume\\\", previousSessionFile? }\\n  └─► resources_discover { reason: \\\"startup\\\" }\\n\\n/fork or /clone\\n  ├─► session_before_fork (can cancel)\\n  ├─► session_shutdown\\n  ├─► session_start { reason: \\\"fork\\\", previousSessionFile }\\n  └─► resources_discover { reason: \\\"startup\\\" }\\n\\n/compact or auto-compaction\\n  ├─► session_before_compact (can cancel or customize)\\n  └─► session_compact\\n\\n/tree navigation\\n  ├─► session_before_tree (can cancel or customize)\\n  └─► session_tree\\n\\n/model or Ctrl+P (model selection/cycling)\\n  ├─► thinking_level_select (if model change changes/clamps thinking level)\\n  └─► model_select\\n\\nthinking level changes (settings, keybinding, pi.setThinkingLevel())\\n  └─► thinking_level_select\\n\\nexit (Ctrl+C, Ctrl+D, SIGHUP, SIGTERM)\\n  └─► session_shutdown\\n```\\n\\n### Startup Events\\n\\n#### project_trust\\n\\nFired before pi decides whether to trust a project with trust inputs (`.pi`, `AGENTS.md`/`CLAUDE.md`, or `.agents/skills`). It runs during startup and when session replacement (for example `/resume`) enters a cwd whose trust has not been resolved in the current process. Only user/global extensions and CLI `-e` extensions participate; project-local extensions are not loaded until after trust is resolved.\\n\\n```typescript\\npi.on(\\\"project_trust\\\", async (event, ctx) => {\\n  // event.cwd - current working directory\\n  // ctx has a limited trust context: cwd, mode, hasUI, and select/confirm/input/notify UI helpers\\n  if (await ctx.ui.confirm(\\\"Trust project?\\\", event.cwd)) {\\n    return { trusted: \\\"yes\\\", remember: true };\\n  }\\n  return { trusted: \\\"undecided\\\" };\\n});\\n```\\n\\nA `project_trust` handler must return `{ trusted: \\\"yes\\\" | \\\"no\\\" | \\\"undecided\\\" }`. A user/global or CLI extension that returns `\\\"yes\\\"` or `\\\"no\\\"` owns the decision; the first yes/no decision wins and suppresses the built-in trust prompt. Use `remember: true` to persist a yes/no decision; otherwise it applies only to the current process. Return `\\\"undecided\\\"` to let later handlers or the built-in trust flow decide. Check `ctx.hasUI` before prompting. If no handler returns yes/no, normal trust resolution continues, including the built-in trust prompt when UI is available.\\n\\n### Resource Events\\n\\n#### resources_discover\\n\\nFired after `session_start` so extensions can contribute additional skill, prompt, and theme paths.\\nThe startup path uses `reason: \\\"startup\\\"`. Reload uses `reason: \\\"reload\\\"`.\\n\\n```typescript\\npi.on(\\\"resources_discover\\\", async (event, _ctx) => {\\n  // event.cwd - current working directory\\n  // event.reason - \\\"startup\\\" | \\\"reload\\\"\\n  return {\\n    skillPaths: [\\\"/path/to/skills\\\"],\\n    promptPaths: [\\\"/path/to/prompts\\\"],\\n    themePaths: [\\\"/path/to/themes\\\"],\\n  };\\n});\\n```\\n\\n### Session Events\\n\\nSee [Session Format](session-format.md) for session storage internals and the SessionManager API.\\n\\n#### session_start\\n\\nFired when a session is started, loaded, or reloaded.\\n\\n```typescript\\npi.on(\\\"session_start\\\", async (event, ctx) => {\\n  // event.reason - \\\"startup\\\" | \\\"reload\\\" | \\\"new\\\" | \\\"resume\\\" | \\\"fork\\\"\\n  // event.previousSessionFile - present for \\\"new\\\", \\\"resume\\\", and \\\"fork\\\"\\n  ctx.ui.notify(`Session: ${ctx.sessionManager.getSessionFile() ?? \\\"ephemeral\\\"}`, \\\"info\\\");\\n});\\n```\\n\\n#### session_before_switch\\n\\nFired before starting a new session (`/new`) or switching sessions (`/resume`).\\n\\n```typescript\\npi.on(\\\"session_before_switch\\\", async (event, ctx) => {\\n  // event.reason - \\\"new\\\" or \\\"resume\\\"\\n  // event.targetSessionFile - session we're switching to (only for \\\"resume\\\")\\n\\n  if (event.reason === \\\"new\\\") {\\n    const ok = await ctx.ui.confirm(\\\"Clear?\\\", \\\"Delete all messages?\\\");\\n    if (!ok) return { cancel: true };\\n  }\\n});\\n```\\n\\nAfter a successful switch or new-session action, pi emits `session_shutdown` for the old extension instance, reloads and rebinds extensions for the new session, then emits `session_start` with `reason: \\\"new\\\" | \\\"resume\\\"` and `previousSessionFile`.\\nDo cleanup work in `session_shutdown`, then reestablish any in-memory state in `session_start`.\\n\\n#### session_before_fork\\n\\nFired when forking via `/fork` or cloning via `/clone`.\\n\\n```typescript\\npi.on(\\\"session_before_fork\\\", async (event, ctx) => {\\n  // event.entryId - ID of the selected entry\\n  // event.position - \\\"before\\\" for /fork, \\\"at\\\" for /clone\\n  return { cancel: true }; // Cancel fork/clone\\n  // OR\\n  return { skipConversationRestore: true }; // Reserved for future conversation restore control\\n});\\n```\\n\\nAfter a successful fork or clone, pi emits `session_shutdown` for the old extension instance, reloads and rebinds extensions for the new session, then emits `session_start` with `reason: \\\"fork\\\"` and `previousSessionFile`.\\nDo cleanup work in `session_shutdown`, then reestablish any in-memory state in `session_start`.\\n\\n#### session_before_compact / session_compact\\n\\nFired on compaction. See [compaction.md](compaction.md) for details.\\n\\n```typescript\\npi.on(\\\"session_before_compact\\\", async (event, ctx) => {\\n  const { preparation, branchEntries, customInstructions, signal } = event;\\n\\n  // Cancel:\\n  return { cancel: true };\\n\\n  // Custom summary:\\n  return {\\n    compaction: {\\n      summary: \\\"...\\\",\\n      firstKeptEntryId: preparation.firstKeptEntryId,\\n      tokensBefore: preparation.tokensBefore,\\n    }\\n  };\\n});\\n\\npi.on(\\\"session_compact\\\", async (event, ctx) => {\\n  // event.compactionEntry - the saved compaction\\n  // event.fromExtension - whether extension provided it\\n});\\n```\\n\\n#### session_before_tree / session_tree\\n\\nFired on `/tree` navigation. See [Sessions](sessions.md) for tree navigation concepts.\\n\\n```typescript\\npi.on(\\\"session_before_tree\\\", async (event, ctx) => {\\n  const { preparation, signal } = event;\\n  return { cancel: true };\\n  // OR provide custom summary:\\n  return { summary: { summary: \\\"...\\\", details: {} } };\\n});\\n\\npi.on(\\\"session_tree\\\", async (event, ctx) => {\\n  // event.newLeafId, oldLeafId, summaryEntry, fromExtension\\n});\\n```\\n\\n#### session_shutdown\\n\\nFired before an extension runtime is torn down.\\n\\n```typescript\\npi.on(\\\"session_shutdown\\\", async (event, ctx) => {\\n  // event.reason - \\\"quit\\\" | \\\"reload\\\" | \\\"new\\\" | \\\"resume\\\" | \\\"fork\\\"\\n  // event.targetSessionFile - destination session for session replacement flows\\n  // Cleanup, save state, etc.\\n});\\n```\\n\\n### Agent Events\\n\\n#### before_agent_start\\n\\nFired after user submits prompt, before agent loop. Can inject a message and/or modify the system prompt.\\n\\n```typescript\\npi.on(\\\"before_agent_start\\\", async (event, ctx) => {\\n  // event.prompt - user's prompt text\\n  // event.images - attached images (if any)\\n  // event.systemPrompt - current chained system prompt for this handler\\n  //   (includes changes from earlier before_agent_start handlers)\\n  // event.systemPromptOptions - structured options used to build the system prompt\\n  //   .customPrompt - any custom system prompt (from --system-prompt, SYSTEM.md, or custom templates)\\n  //   .selectedTools - tools currently active in the prompt\\n  //   .toolSnippets - one-line descriptions for each tool\\n  //   .promptGuidelines - custom guideline bullets\\n  //   .appendSystemPrompt - text from --append-system-prompt flags\\n  //   .cwd - working directory\\n  //   .contextFiles - AGENTS.md files and other loaded context files\\n  //   .skills - loaded skills\\n\\n  return {\\n    // Inject a persistent message (stored in session, sent to LLM)\\n    message: {\\n      customType: \\\"my-extension\\\",\\n      content: \\\"Additional context for the LLM\\\",\\n      display: true,\\n    },\\n    // Replace the system prompt for this turn (chained across extensions)\\n    systemPrompt: event.systemPrompt + \\\"\\\\n\\\\nExtra instructions for this turn...\\\",\\n  };\\n});\\n```\\n\\nThe `systemPromptOptions` field gives extensions access to the same structured data Pi uses to build the system prompt. This lets you inspect what Pi has loaded — custom prompts, guidelines, tool snippets, context files, skills — without re-discovering resources or re-parsing flags. Use it when your extension needs to make deep, informed changes to the system prompt while respecting user-provided configuration.\\n\\nInside `before_agent_start`, `event.systemPrompt` and `ctx.getSystemPrompt()` both reflect the chained system prompt as of the current handler. Later `before_agent_start` handlers can still modify it again.\\n\\n#### agent_start / agent_end\\n\\nFired once per user prompt.\\n\\n```typescript\\npi.on(\\\"agent_start\\\", async (_event, ctx) => {});\\n\\npi.on(\\\"agent_end\\\", async (event, ctx) => {\\n  // event.messages - messages from this prompt\\n});\\n```\\n\\n#### turn_start / turn_end\\n\\nFired for each turn (one LLM response + tool calls).\\n\\n```typescript\\npi.on(\\\"turn_start\\\", async (event, ctx) => {\\n  // event.turnIndex, event.timestamp\\n});\\n\\npi.on(\\\"turn_end\\\", async (event, ctx) => {\\n  // event.turnIndex, event.message, event.toolResults\\n});\\n```\\n\\n#### message_start / message_update / message_end\\n\\nFired for message lifecycle updates.\\n\\n- `message_start` and `message_end` fire for user, assistant, and toolResult messages.\\n- `message_update` fires for assistant streaming updates.\\n- `message_end` handlers can return `{ message }` to replace the finalized message. The replacement must keep the same `role`.\\n\\n```typescript\\npi.on(\\\"message_start\\\", async (event, ctx) => {\\n  // event.message\\n});\\n\\npi.on(\\\"message_update\\\", async (event, ctx) => {\\n  // event.message\\n  // event.assistantMessageEvent (token-by-token stream event)\\n});\\n\\npi.on(\\\"message_end\\\", async (event, ctx) => {\\n  if (event.message.role !== \\\"assistant\\\") return;\\n\\n  return {\\n    message: {\\n      ...event.message,\\n      usage: {\\n        ...event.message.usage,\\n        cost: {\\n          ...event.message.usage.cost,\\n          total: 0.123,\\n        },\\n      },\\n    },\\n  };\\n});\\n```\\n\\n#### tool_execution_start / tool_execution_update / tool_execution_end\\n\\nFired for tool execution lifecycle updates.\\n\\nIn parallel tool mode:\\n- `tool_execution_start` is emitted in assistant source order during the preflight phase\\n- `tool_execution_update` events may interleave across tools\\n- `tool_execution_end` is emitted in tool completion order after each tool is finalized\\n- final `toolResult` message events are still emitted later in assistant source order\\n\\n```typescript\\npi.on(\\\"tool_execution_start\\\", async (event, ctx) => {\\n  // event.toolCallId, event.toolName, event.args\\n});\\n\\npi.on(\\\"tool_execution_update\\\", async (event, ctx) => {\\n  // event.toolCallId, event.toolName, event.args, event.partialResult\\n});\\n\\npi.on(\\\"tool_execution_end\\\", async (event, ctx) => {\\n  // event.toolCallId, event.toolName, event.result, event.isError\\n});\\n```\\n\\n#### context\\n\\nFired before each LLM call. Modify messages non-destructively. See [Session Format](session-format.md) for message types.\\n\\n```typescript\\npi.on(\\\"context\\\", async (event, ctx) => {\\n  // event.messages - deep copy, safe to modify\\n  const filtered = event.messages.filter(m => !shouldPrune(m));\\n  return { messages: filtered };\\n});\\n```\\n\\n#### before_provider_request\\n\\nFired after the provider-specific payload is built, right before the request is sent. Handlers run in extension load order. Returning `undefined` keeps the payload unchanged. Returning any other value replaces the payload for later handlers and for the actual request.\\n\\nThis hook can rewrite provider-level system instructions or remove them entirely. Those payload-level changes are not reflected by `ctx.getSystemPrompt()`, which reports Pi's system prompt string rather than the final serialized provider payload.\\n\\n```typescript\\npi.on(\\\"before_provider_request\\\", (event, ctx) => {\\n  console.log(JSON.stringify(event.payload, null, 2));\\n\\n  // Optional: replace payload\\n  // return { ...event.payload, temperature: 0 };\\n});\\n```\\n\\nThis is mainly useful for debugging provider serialization and cache behavior.\\n\\n#### after_provider_response\\n\\nFired after an HTTP response is received and before its stream body is consumed. Handlers run in extension load order.\\n\\n```typescript\\npi.on(\\\"after_provider_response\\\", (event, ctx) => {\\n  // event.status - HTTP status code\\n  // event.headers - normalized response headers\\n  if (event.status === 429) {\\n    console.log(\\\"rate limited\\\", event.headers[\\\"retry-after\\\"]);\\n  }\\n});\\n```\\n\\nHeader availability depends on provider and transport. Providers that abstract HTTP responses may not expose headers.\\n\\n### Model Events\\n\\n#### model_select\\n\\nFired when the model changes via `/model` command, model cycling (`Ctrl+P`), or session restore.\\n\\n```typescript\\npi.on(\\\"model_select\\\", async (event, ctx) => {\\n  // event.model - newly selected model\\n  // event.previousModel - previous model (undefined if first selection)\\n  // event.source - \\\"set\\\" | \\\"cycle\\\" | \\\"restore\\\"\\n\\n  const prev = event.previousModel\\n    ? `${event.previousModel.provider}/${event.previousModel.id}`\\n    : \\\"none\\\";\\n  const next = `${event.model.provider}/${event.model.id}`;\\n\\n  ctx.ui.notify(`Model changed (${event.source}): ${prev} -> ${next}`, \\\"info\\\");\\n});\\n```\\n\\nUse this to update UI elements (status bars, footers) or perform model-specific initialization when the active model changes.\\n\\n#### thinking_level_select\\n\\nFired when the thinking level changes. This is notification-only; handler return values are ignored.\\n\\n```typescript\\npi.on(\\\"thinking_level_select\\\", async (event, ctx) => {\\n  // event.level - newly selected thinking level\\n  // event.previousLevel - previous thinking level\\n\\n  ctx.ui.setStatus(\\\"thinking\\\", `thinking: ${event.level}`);\\n});\\n```\\n\\nUse this to update extension UI when `pi.setThinkingLevel()`, model changes, or built-in thinking-level controls change the active thinking level.\\n\\n### Tool Events\\n\\n#### tool_call\\n\\nFired after `tool_execution_start`, before the tool executes. **Can block.** Use `isToolCallEventType` to narrow and get typed inputs.\\n\\nBefore `tool_call` runs, pi waits for previously emitted Agent events to finish draining through `AgentSession`. This means `ctx.sessionManager` is up to date through the current assistant tool-calling message.\\n\\nIn the default parallel tool execution mode, sibling tool calls from the same assistant message are preflighted sequentially, then executed concurrently. `tool_call` is not guaranteed to see sibling tool results from that same assistant message in `ctx.sessionManager`.\\n\\n`event.input` is mutable. Mutate it in place to patch tool arguments before execution.\\n\\nBehavior guarantees:\\n- Mutations to `event.input` affect the actual tool execution\\n- Later `tool_call` handlers see mutations made by earlier handlers\\n- No re-validation is performed after your mutation\\n- Return values from `tool_call` only control blocking via `{ block: true, reason?: string }`\\n\\n```typescript\\nimport { isToolCallEventType } from \\\"@earendil-works/pi-coding-agent\\\";\\n\\npi.on(\\\"tool_call\\\", async (event, ctx) => {\\n  // event.toolName - \\\"bash\\\", \\\"read\\\", \\\"write\\\", \\\"edit\\\", etc.\\n  // event.toolCallId\\n  // event.input - tool parameters (mutable)\\n\\n  // Built-in tools: no type params needed\\n  if (isToolCallEventType(\\\"bash\\\", event)) {\\n    // event.input is { command: string; timeout?: number }\\n    event.input.command = `source ~/.profile\\\\n${event.input.command}`;\\n\\n    if (event.input.command.includes(\\\"rm -rf\\\")) {\\n      return { block: true, reason: \\\"Dangerous command\\\" };\\n    }\\n  }\\n\\n  if (isToolCallEventType(\\\"read\\\", event)) {\\n    // event.input is { path: string; offset?: number; limit?: number }\\n    console.log(`Reading: ${event.input.path}`);\\n  }\\n});\\n```\\n\\n#### Typing custom tool input\\n\\nCustom tools should export their input type:\\n\\n```typescript\\n// my-extension.ts\\nexport type MyToolInput = Static<typeof myToolSchema>;\\n```\\n\\nUse `isToolCallEventType` with explicit type parameters:\\n\\n```typescript\\nimport { isToolCallEventType } from \\\"@earendil-works/pi-coding-agent\\\";\\nimport type { MyToolInput } from \\\"my-extension\\\";\\n\\npi.on(\\\"tool_call\\\", (event) => {\\n  if (isToolCallEventType<\\\"my_tool\\\", MyToolInput>(\\\"my_tool\\\", event)) {\\n    event.input.action;  // typed\\n  }\\n});\\n```\\n\\n#### tool_result\\n\\nFired after tool execution finishes and before `tool_execution_end` plus the final tool result message events are emitted. **Can modify result.**\\n\\nIn parallel tool mode, `tool_result` and `tool_execution_end` may interleave in tool completion order, while final `toolResult` message events are still emitted later in assistant source order.\\n\\n`tool_result` handlers chain like middleware:\\n- Handlers run in extension load order\\n- Each handler sees the latest result after previous handler changes\\n- Handlers can return partial patches (`content`, `details`, or `isError`); omitted fields keep their current values\\n\\nUse `ctx.signal` for nested async work inside the handler. This lets Esc cancel model calls, `fetch()`, and other abort-aware operations started by the extension.\\n\\n```typescript\\nimport { isBashToolResult } from \\\"@earendil-works/pi-coding-agent\\\";\\n\\npi.on(\\\"tool_result\\\", async (event, ctx) => {\\n  // event.toolName, event.toolCallId, event.input\\n  // event.content, event.details, event.isError\\n\\n  if (isBashToolResult(event)) {\\n    // event.details is typed as BashToolDetails\\n  }\\n\\n  const response = await fetch(\\\"https://example.com/summarize\\\", {\\n    method: \\\"POST\\\",\\n    body: JSON.stringify({ content: event.content }),\\n    signal: ctx.signal,\\n  });\\n\\n  // Modify result:\\n  return { content: [...], details: {...}, isError: false };\\n});\\n```\\n\\n### User Bash Events\\n\\n#### user_bash\\n\\nFired when user executes `!` or `!!` commands. **Can intercept.**\\n\\n```typescript\\nimport { createLocalBashOperations } from \\\"@earendil-works/pi-coding-agent\\\";\\n\\npi.on(\\\"user_bash\\\", (event, ctx) => {\\n  // event.command - the bash command\\n  // event.excludeFromContext - true if !! prefix\\n  // event.cwd - working directory\\n\\n  // Option 1: Provide custom operations (e.g., SSH)\\n  return { operations: remoteBashOps };\\n\\n  // Option 2: Wrap pi's built-in local bash backend\\n  const local = createLocalBashOperations();\\n  return {\\n    operations: {\\n      exec(command, cwd, options) {\\n        return local.exec(`source ~/.profile\\\\n${command}`, cwd, options);\\n      }\\n    }\\n  };\\n\\n  // Option 3: Full replacement - return result directly\\n  return { result: { output: \\\"...\\\", exitCode: 0, cancelled: false, truncated: false } };\\n});\\n```\\n\\n### Input Events\\n\\n#### input\\n\\nFired when user input is received, after extension commands are checked but before skill and template expansion. The event sees the raw input text, so `/skill:foo` and `/template` are not yet expanded.\\n\\n**Processing order:**\\n1. Extension commands (`/cmd`) checked first - if found, handler runs and input event is skipped\\n2. `input` event fires - can intercept, transform, or handle\\n3. If not handled: skill commands (`/skill:name`) expanded to skill content\\n4. If not handled: prompt templates (`/template`) expanded to template content\\n5. Agent processing begins (`before_agent_start`, etc.)\\n\\n```typescript\\npi.on(\\\"input\\\", async (event, ctx) => {\\n  // event.text - raw input (before skill/template expansion)\\n  // event.images - attached images, if any\\n  // event.source - \\\"interactive\\\" (typed), \\\"rpc\\\" (API), or \\\"extension\\\" (via sendUserMessage)\\n  // event.streamingBehavior - \\\"steer\\\" | \\\"followUp\\\" | undefined\\n  //   undefined when idle, \\\"steer\\\" for mid-stream interrupts,\\n  //   \\\"followUp\\\" for messages queued until the agent finishes\\n\\n  // Transform: rewrite input before expansion\\n  if (event.text.startsWith(\\\"?quick \\\"))\\n    return { action: \\\"transform\\\", text: `Respond briefly: ${event.text.slice(7)}` };\\n\\n  // Handle: respond without LLM (extension shows its own feedback)\\n  if (event.text === \\\"ping\\\") {\\n    ctx.ui.notify(\\\"pong\\\", \\\"info\\\");\\n    return { action: \\\"handled\\\" };\\n  }\\n\\n  // Route by source: skip processing for extension-injected messages\\n  if (event.source === \\\"extension\\\") return { action: \\\"continue\\\" };\\n\\n  // Intercept skill commands before expansion\\n  if (event.text.startsWith(\\\"/skill:\\\")) {\\n    // Could transform, block, or let pass through\\n  }\\n\\n  return { action: \\\"continue\\\" };  // Default: pass through to expansion\\n});\\n```\\n\\n**Results:**\\n- `continue` - pass through unchanged (default if handler returns nothing)\\n- `transform` - modify text/images, then continue to expansion\\n- `handled` - skip agent entirely (first handler to return this wins)\\n\\nTransforms chain across handlers. See [input-transform.ts](../examples/extensions/input-transform.ts) and [input-transform-streaming.ts](../examples/extensions/input-transform-streaming.ts) for `streamingBehavior`-aware routing.\\n\\n## ExtensionContext\\n\\nAll handlers receive `ctx: ExtensionContext`.\\n\\n### ctx.ui\\n\\nUI methods for user interaction. See [Custom UI](#custom-ui) for full details.\\n\\n### ctx.mode\\n\\nCurrent run mode: `\\\"tui\\\"`, `\\\"rpc\\\"`, `\\\"json\\\"`, or `\\\"print\\\"`. Use `ctx.mode === \\\"tui\\\"` to guard terminal-only features such as `custom()`, component factories, terminal input, and direct TUI rendering.\\n\\n### ctx.hasUI\\n\\n`true` in TUI and RPC modes. `false` in print mode (`-p`) and JSON mode. Use this to guard dialog methods (`select`, `confirm`, `input`, `editor`) and fire-and-forget methods (`notify`, `setStatus`, `setWidget`, `setTitle`, `setEditorText`) that work in both TUI and RPC modes. In RPC mode, some TUI-specific methods are no-ops or return defaults (see [rpc.md](rpc.md#extension-ui-protocol)).\\n\\n### ctx.cwd\\n\\nCurrent working directory.\\n\\n### ctx.sessionManager\\n\\nRead-only access to session state. See [Session Format](session-format.md) for the full SessionManager API and entry types.\\n\\nFor `tool_call`, this state is synchronized through the current assistant message before handlers run. In parallel tool execution mode it is still not guaranteed to include sibling tool results from the same assistant message.\\n\\n```typescript\\nctx.sessionManager.getEntries()       // All entries\\nctx.sessionManager.getBranch()        // Current branch\\nctx.sessionManager.getLeafId()        // Current leaf entry ID\\n```\\n\\n### ctx.modelRegistry / ctx.model\\n\\nAccess to models and API keys.\\n\\n### ctx.signal\\n\\nThe current agent abort signal, or `undefined` when no agent turn is active.\\n\\nUse this for abort-aware nested work started by extension handlers, for example:\\n- `fetch(..., { signal: ctx.signal })`\\n- model calls that accept `signal`\\n- file or process helpers that accept `AbortSignal`\\n\\n`ctx.signal` is typically defined during active turn events such as `tool_call`, `tool_result`, `message_update`, and `turn_end`.\\nIt is usually `undefined` in idle or non-turn contexts such as session events, extension commands, and shortcuts fired while pi is idle.\\n\\n```typescript\\npi.on(\\\"tool_result\\\", async (event, ctx) => {\\n  const response = await fetch(\\\"https://example.com/api\\\", {\\n    method: \\\"POST\\\",\\n    body: JSON.stringify(event),\\n    signal: ctx.signal,\\n  });\\n\\n  const data = await response.json();\\n  return { details: data };\\n});\\n```\\n\\n### ctx.isIdle() / ctx.abort() / ctx.hasPendingMessages()\\n\\nControl flow helpers.\\n\\n### ctx.shutdown()\\n\\nRequest a graceful shutdown of pi.\\n\\n- **Interactive mode:** Deferred until the agent becomes idle (after processing all queued steering and follow-up messages).\\n- **RPC mode:** Deferred until the next idle state (after completing the current command response, when waiting for the next command).\\n- **Print mode:** No-op. The process exits automatically when all prompts are processed.\\n\\nEmits `session_shutdown` event to all extensions before exiting. Available in all contexts (event handlers, tools, commands, shortcuts).\\n\\n```typescript\\npi.on(\\\"tool_call\\\", (event, ctx) => {\\n  if (isFatal(event.input)) {\\n    ctx.shutdown();\\n  }\\n});\\n```\\n\\n### ctx.getContextUsage()\\n\\nReturns current context usage for the active model. Uses last assistant usage when available, then estimates tokens for trailing messages.\\n\\n```typescript\\nconst usage = ctx.getContextUsage();\\nif (usage && usage.tokens > 100_000) {\\n  // ...\\n}\\n```\\n\\n### ctx.compact()\\n\\nTrigger compaction without awaiting completion. Use `onComplete` and `onError` for follow-up actions.\\n\\n```typescript\\nctx.compact({\\n  customInstructions: \\\"Focus on recent changes\\\",\\n  onComplete: (result) => {\\n    ctx.ui.notify(\\\"Compaction completed\\\", \\\"info\\\");\\n  },\\n  onError: (error) => {\\n    ctx.ui.notify(`Compaction failed: ${error.message}`, \\\"error\\\");\\n  },\\n});\\n```\\n\\n### ctx.getSystemPrompt()\\n\\nReturns Pi's current system prompt string.\\n\\n- During `before_agent_start`, this reflects chained system-prompt changes made so far for the current turn.\\n- It does not include later `context` message mutations.\\n- It does not include `before_provider_request` payload rewrites.\\n- If later-loaded extensions run after yours, they can still change what is ultimately sent.\\n\\n```typescript\\npi.on(\\\"before_agent_start\\\", (event, ctx) => {\\n  const prompt = ctx.getSystemPrompt();\\n  console.log(`System prompt length: ${prompt.length}`);\\n});\\n```\\n\\n## ExtensionCommandContext\\n\\nCommand handlers receive `ExtensionCommandContext`, which extends `ExtensionContext` with session control methods. These are only available in commands because they can deadlock if called from event handlers.\\n\\n### ctx.getSystemPromptOptions()\\n\\nReturns the base inputs Pi currently uses to build the system prompt.\\n\\n```typescript\\nconst options = ctx.getSystemPromptOptions();\\nconst contextPaths = options.contextFiles?.map((file) => file.path) ?? [];\\n```\\n\\nThis has the same shape and mutability as `before_agent_start` `event.systemPromptOptions`: custom prompt, active tools, tool snippets, prompt guidelines, appended system prompt text, cwd, loaded context files, and loaded skills. It may include full context file contents, so treat it as sensitive extension-local data and avoid exposing it through command lists, logs, or autocomplete metadata.\\n\\nThis reports the current base prompt inputs. It does not include per-turn `before_agent_start` chained system-prompt changes, later `context` event message mutations, or `before_provider_request` payload rewrites.\\n\\n### ctx.waitForIdle()\\n\\nWait for the agent to finish streaming:\\n\\n```typescript\\npi.registerCommand(\\\"my-cmd\\\", {\\n  handler: async (args, ctx) => {\\n    await ctx.waitForIdle();\\n    // Agent is now idle, safe to modify session\\n  },\\n});\\n```\\n\\n### ctx.newSession(options?)\\n\\nCreate a new session:\\n\\n```typescript\\nconst parentSession = ctx.sessionManager.getSessionFile();\\nconst kickoff = \\\"Continue in the replacement session\\\";\\n\\nconst result = await ctx.newSession({\\n  parentSession,\\n  setup: async (sm) => {\\n    sm.appendMessage({\\n      role: \\\"user\\\",\\n      content: [{ type: \\\"text\\\", text: \\\"Context from previous session...\\\" }],\\n      timestamp: Date.now(),\\n    });\\n  },\\n  withSession: async (ctx) => {\\n    // Use only the replacement-session ctx here.\\n    await ctx.sendUserMessage(kickoff);\\n  },\\n});\\n\\nif (result.cancelled) {\\n  // An extension cancelled the new session\\n}\\n```\\n\\nOptions:\\n- `parentSession`: parent session file to record in the new session header\\n- `setup`: mutate the new session's `SessionManager` before `withSession` runs\\n- `withSession`: run post-switch work against a fresh replacement-session context. Do not use captured old `pi` / command `ctx`; see [Session replacement lifecycle and footguns](#session-replacement-lifecycle-and-footguns).\\n\\n### ctx.fork(entryId, options?)\\n\\nFork from a specific entry, creating a new session file:\\n\\n```typescript\\nconst result = await ctx.fork(\\\"entry-id-123\\\", {\\n  withSession: async (ctx) => {\\n    // Use only the replacement-session ctx here.\\n    ctx.ui.notify(\\\"Now in the forked session\\\", \\\"info\\\");\\n  },\\n});\\nif (result.cancelled) {\\n  // An extension cancelled the fork\\n}\\n\\nconst cloneResult = await ctx.fork(\\\"entry-id-456\\\", { position: \\\"at\\\" });\\nif (cloneResult.cancelled) {\\n  // An extension cancelled the clone\\n}\\n```\\n\\nOptions:\\n- `position`: `\\\"before\\\"` (default) forks before the selected user message, restoring that prompt into the editor\\n- `position`: `\\\"at\\\"` duplicates the active path through the selected entry without restoring editor text\\n- `withSession`: run post-switch work against a fresh replacement-session context. Do not use captured old `pi` / command `ctx`; see [Session replacement lifecycle and footguns](#session-replacement-lifecycle-and-footguns).\\n\\n### ctx.navigateTree(targetId, options?)\\n\\nNavigate to a different point in the session tree:\\n\\n```typescript\\nconst result = await ctx.navigateTree(\\\"entry-id-456\\\", {\\n  summarize: true,\\n  customInstructions: \\\"Focus on error handling changes\\\",\\n  replaceInstructions: false, // true = replace default prompt entirely\\n  label: \\\"review-checkpoint\\\",\\n});\\n```\\n\\nOptions:\\n- `summarize`: Whether to generate a summary of the abandoned branch\\n- `customInstructions`: Custom instructions for the summarizer\\n- `replaceInstructions`: If true, `customInstructions` replaces the default prompt instead of being appended\\n- `label`: Label to attach to the branch summary entry (or target entry if not summarizing)\\n\\n### ctx.switchSession(sessionPath, options?)\\n\\nSwitch to a different session file:\\n\\n```typescript\\nconst result = await ctx.switchSession(\\\"/path/to/session.jsonl\\\", {\\n  withSession: async (ctx) => {\\n    await ctx.sendUserMessage(\\\"Resume work in the replacement session\\\");\\n  },\\n});\\nif (result.cancelled) {\\n  // An extension cancelled the switch via session_before_switch\\n}\\n```\\n\\nOptions:\\n- `withSession`: run post-switch work against a fresh replacement-session context. Do not use captured old `pi` / command `ctx`; see [Session replacement lifecycle and footguns](#session-replacement-lifecycle-and-footguns).\\n\\nTo discover available sessions, use the static `SessionManager.list()` or `SessionManager.listAll()` methods:\\n\\n```typescript\\nimport { SessionManager } from \\\"@earendil-works/pi-coding-agent\\\";\\n\\npi.registerCommand(\\\"switch\\\", {\\n  description: \\\"Switch to another session\\\",\\n  handler: async (args, ctx) => {\\n    const sessions = await SessionManager.list(ctx.cwd);\\n    if (sessions.length === 0) return;\\n    const choice = await ctx.ui.select(\\n      \\\"Pick session:\\\",\\n      sessions.map(s => s.file),\\n    );\\n    if (choice) {\\n      await ctx.switchSession(choice, {\\n        withSession: async (ctx) => {\\n          ctx.ui.notify(\\\"Switched session\\\", \\\"info\\\");\\n        },\\n      });\\n    }\\n  },\\n});\\n```\\n\\n### Session replacement lifecycle and footguns\\n\\n`withSession` receives a fresh `ReplacedSessionContext`, which extends `ExtensionCommandContext` with async `sendMessage()` and `sendUserMessage()` helpers bound to the replacement session.\\n\\nLifecycle and footguns:\\n- `withSession` runs only after the old session has emitted `session_shutdown`, the old runtime has been torn down, the replacement session has been rebound, and the new extension instance has already received `session_start`.\\n- The callback still executes in the original closure, not inside the new extension instance. That means your old extension instance may already have run its shutdown cleanup before `withSession` starts.\\n- Captured old `pi` / old command `ctx` session-bound objects are stale after replacement and will throw if used. Use only the `ctx` passed to `withSession` for session-bound work.\\n- Previously extracted raw objects are still your responsibility. For example, if you capture `const sm = ctx.sessionManager` before replacement, `sm` is still the old `SessionManager` object. Do not reuse it after replacement.\\n- Code in `withSession` should assume any state invalidated by your `session_shutdown` handler is already gone. Only capture plain data that survives shutdown cleanly, such as strings, ids, and serialized config.\\n\\nSafe pattern:\\n\\n```typescript\\npi.registerCommand(\\\"handoff\\\", {\\n  handler: async (_args, ctx) => {\\n    const kickoff = \\\"Continue from the replacement session\\\";\\n    await ctx.newSession({\\n      withSession: async (ctx) => {\\n        await ctx.sendUserMessage(kickoff);\\n      },\\n    });\\n  },\\n});\\n```\\n\\nUnsafe pattern:\\n\\n```typescript\\npi.registerCommand(\\\"handoff\\\", {\\n  handler: async (_args, ctx) => {\\n    const oldSessionManager = ctx.sessionManager;\\n    await ctx.newSession({\\n      withSession: async (_ctx) => {\\n        // stale old objects: do not do this\\n        oldSessionManager.getSessionFile();\\n        pi.sendUserMessage(\\\"wrong\\\");\\n      },\\n    });\\n  },\\n});\\n```\\n\\n### ctx.reload()\\n\\nRun the same reload flow as `/reload`.\\n\\n```typescript\\npi.registerCommand(\\\"reload-runtime\\\", {\\n  description: \\\"Reload extensions, skills, prompts, and themes\\\",\\n  handler: async (_args, ctx) => {\\n    await ctx.reload();\\n    return;\\n  },\\n});\\n```\\n\\nImportant behavior:\\n- `await ctx.reload()` emits `session_shutdown` for the current extension runtime\\n- It then reloads resources and emits `session_start` with `reason: \\\"reload\\\"` and `resources_discover` with reason `\\\"reload\\\"`\\n- The currently running command handler still continues in the old call frame\\n- Code after `await ctx.reload()` still runs from the pre-reload version\\n- Code after `await ctx.reload()` must not assume old in-memory extension state is still valid\\n- After the handler returns, future commands/events/tool calls use the new extension version\\n\\nFor predictable behavior, treat reload as terminal for that handler (`await ctx.reload(); return;`).\\n\\nTools run with `ExtensionContext`, so they cannot call `ctx.reload()` directly. Use a command as the reload entrypoint, then expose a tool that queues that command as a follow-up user message.\\n\\nExample tool the LLM can call to trigger reload:\\n\\n```typescript\\nimport type { ExtensionAPI } from \\\"@earendil-works/pi-coding-agent\\\";\\nimport { Type } from \\\"typebox\\\";\\n\\nexport default function (pi: ExtensionAPI) {\\n  pi.registerCommand(\\\"reload-runtime\\\", {\\n    description: \\\"Reload extensions, skills, prompts, and themes\\\",\\n    handler: async (_args, ctx) => {\\n      await ctx.reload();\\n      return;\\n    },\\n  });\\n\\n  pi.registerTool({\\n    name: \\\"reload_runtime\\\",\\n    label: \\\"Reload Runtime\\\",\\n    description: \\\"Reload extensions, skills, prompts, and themes\\\",\\n    parameters: Type.Object({}),\\n    async execute() {\\n      pi.sendUserMessage(\\\"/reload-runtime\\\", { deliverAs: \\\"followUp\\\" });\\n      return {\\n        content: [{ type: \\\"text\\\", text: \\\"Queued /reload-runtime as a follow-up command.\\\" }],\\n      };\\n    },\\n  });\\n}\\n```\\n\\n## ExtensionAPI Methods\\n\\n### pi.on(event, handler)\\n\\nSubscribe to events. See [Events](#events) for event types and return values.\\n\\n### pi.registerTool(definition)\\n\\nRegister a custom tool callable by the LLM. See [Custom Tools](#custom-tools) for full details.\\n\\n`pi.registerTool()` works both during extension load and after startup. You can call it inside `session_start`, command handlers, or other event handlers. New tools are refreshed immediately in the same session, so they appear in `pi.getAllTools()` and are callable by the LLM without `/reload`.\\n\\nUse `pi.setActiveTools()` to enable or disable tools (including dynamically added tools) at runtime.\\n\\nUse `promptSnippet` to opt a custom tool into a one-line entry in `Available tools`, and `promptGuidelines` to append tool-specific bullets to the default `Guidelines` section when the tool is active.\\n\\n**Important:** `promptGuidelines` bullets are appended flat to the `Guidelines` section with no tool name prefix. Each guideline must name the tool it refers to — avoid \\\"Use this tool when...\\\" because the LLM cannot tell which tool \\\"this\\\" means. Write \\\"Use my_tool when...\\\" instead.\\n\\nSee [dynamic-tools.ts](../examples/extensions/dynamic-tools.ts) for a full example.\\n\\n```typescript\\nimport { Type } from \\\"typebox\\\";\\nimport { StringEnum } from \\\"@earendil-works/pi-ai\\\";\\n\\npi.registerTool({\\n  name: \\\"my_tool\\\",\\n  label: \\\"My Tool\\\",\\n  description: \\\"What this tool does\\\",\\n  promptSnippet: \\\"Summarize or transform text according to action\\\",\\n  promptGuidelines: [\\\"Use my_tool when the user asks to summarize previously generated text.\\\"],\\n  parameters: Type.Object({\\n    action: StringEnum([\\\"list\\\", \\\"add\\\"] as const),\\n    text: Type.Optional(Type.String()),\\n  }),\\n  prepareArguments(args) {\\n    // Optional compatibility shim. Runs before schema validation.\\n    // Return the current schema shape, for example to fold legacy fields\\n    // into the modern parameter object.\\n    return args;\\n  },\\n\\n  async execute(toolCallId, params, signal, onUpdate, ctx) {\\n    // Stream progress\\n    onUpdate?.({ content: [{ type: \\\"text\\\", text: \\\"Working...\\\" }] });\\n\\n    return {\\n      content: [{ type: \\\"text\\\", text: \\\"Done\\\" }],\\n      details: { result: \\\"...\\\" },\\n    };\\n  },\\n\\n  // Optional: Custom rendering\\n  renderCall(args, theme, context) { ... },\\n  renderResult(result, options, theme, context) { ... },\\n});\\n```\\n\\n### pi.sendMessage(message, options?)\\n\\nInject a custom message into the session.\\n\\n```typescript\\npi.sendMessage({\\n  customType: \\\"my-extension\\\",\\n  content: \\\"Message text\\\",\\n  display: true,\\n  details: { ... },\\n}, {\\n  triggerTurn: true,\\n  deliverAs: \\\"steer\\\",\\n});\\n```\\n\\n**Options:**\\n- `deliverAs` - Delivery mode:\\n  - `\\\"steer\\\"` (default) - Queues the message while streaming. Delivered after the current assistant turn finishes executing its tool calls, before the next LLM call.\\n  - `\\\"followUp\\\"` - Waits for agent to finish. Delivered only when agent has no more tool calls.\\n  - `\\\"nextTurn\\\"` - Queued for next user prompt. Does not interrupt or trigger anything.\\n- `triggerTurn: true` - If agent is idle, trigger an LLM response immediately. Only applies to `\\\"steer\\\"` and `\\\"followUp\\\"` modes (ignored for `\\\"nextTurn\\\"`).\\n\\n### pi.sendUserMessage(content, options?)\\n\\nSend a user message to the agent. Unlike `sendMessage()` which sends custom messages, this sends an actual user message that appears as if typed by the user. Always triggers a turn.\\n\\n```typescript\\n// Simple text message\\npi.sendUserMessage(\\\"What is 2+2?\\\");\\n\\n// With content array (text + images)\\npi.sendUserMessage([\\n  { type: \\\"text\\\", text: \\\"Describe this image:\\\" },\\n  { type: \\\"image\\\", source: { type: \\\"base64\\\", mediaType: \\\"image/png\\\", data: \\\"...\\\" } },\\n]);\\n\\n// During streaming - must specify delivery mode\\npi.sendUserMessage(\\\"Focus on error handling\\\", { deliverAs: \\\"steer\\\" });\\npi.sendUserMessage(\\\"And then summarize\\\", { deliverAs: \\\"followUp\\\" });\\n```\\n\\n**Options:**\\n- `deliverAs` - Required when agent is streaming:\\n  - `\\\"steer\\\"` - Queues the message for delivery after the current assistant turn finishes executing its tool calls\\n  - `\\\"followUp\\\"` - Waits for agent to finish all tools\\n\\nWhen not streaming, the message is sent immediately and triggers a new turn. When streaming without `deliverAs`, throws an error.\\n\\nSee [send-user-message.ts](../examples/extensions/send-user-message.ts) for a complete example.\\n\\n### pi.appendEntry(customType, data?)\\n\\nPersist extension state (does NOT participate in LLM context).\\n\\n```typescript\\npi.appendEntry(\\\"my-state\\\", { count: 42 });\\n\\n// Restore on reload\\npi.on(\\\"session_start\\\", async (_event, ctx) => {\\n  for (const entry of ctx.sessionManager.getEntries()) {\\n    if (entry.type === \\\"custom\\\" && entry.customType === \\\"my-state\\\") {\\n      // Reconstruct from entry.data\\n    }\\n  }\\n});\\n```\\n\\n### pi.setSessionName(name)\\n\\nSet the session display name (shown in session selector instead of first message).\\n\\n```typescript\\npi.setSessionName(\\\"Refactor auth module\\\");\\n```\\n\\n### pi.getSessionName()\\n\\nGet the current session name, if set.\\n\\n```typescript\\nconst name = pi.getSessionName();\\nif (name) {\\n  console.log(`Session: ${name}`);\\n}\\n```\\n\\n### pi.setLabel(entryId, label)\\n\\nSet or clear a label on an entry. Labels are user-defined markers for bookmarking and navigation (shown in `/tree` selector).\\n\\n```typescript\\n// Set a label\\npi.setLabel(entryId, \\\"checkpoint-before-refactor\\\");\\n\\n// Clear a label\\npi.setLabel(entryId, undefined);\\n\\n// Read labels via sessionManager\\nconst label = ctx.sessionManager.getLabel(entryId);\\n```\\n\\nLabels persist in the session and survive restarts. Use them to mark important points (turns, checkpoints) in the conversation tree.\\n\\n### pi.registerCommand(name, options)\\n\\nRegister a command.\\n\\nIf multiple extensions register the same command name, pi keeps them all and assigns numeric invocation suffixes in load order, for example `/review:1` and `/review:2`.\\n\\n```typescript\\npi.registerCommand(\\\"stats\\\", {\\n  description: \\\"Show session statistics\\\",\\n  handler: async (args, ctx) => {\\n    const count = ctx.sessionManager.getEntries().length;\\n    ctx.ui.notify(`${count} entries`, \\\"info\\\");\\n  }\\n});\\n```\\n\\nOptional: add argument auto-completion for `/command ...`:\\n\\n```typescript\\nimport type { AutocompleteItem } from \\\"@earendil-works/pi-tui\\\";\\n\\npi.registerCommand(\\\"deploy\\\", {\\n  description: \\\"Deploy to an environment\\\",\\n  getArgumentCompletions: (prefix: string): AutocompleteItem[] | null => {\\n    const envs = [\\\"dev\\\", \\\"staging\\\", \\\"prod\\\"];\\n    const items = envs.map((e) => ({ value: e, label: e }));\\n    const filtered = items.filter((i) => i.value.startsWith(prefix));\\n    return filtered.length > 0 ? filtered : null;\\n  },\\n  handler: async (args, ctx) => {\\n    ctx.ui.notify(`Deploying: ${args}`, \\\"info\\\");\\n  },\\n});\\n```\\n\\n### pi.getCommands()\\n\\nGet the slash commands available for invocation via `prompt` in the current session. Includes extension commands, prompt templates, and skill commands.\\nThe list matches the RPC `get_commands` ordering: extensions first, then templates, then skills.\\n\\n```typescript\\nconst commands = pi.getCommands();\\nconst bySource = commands.filter((command) => command.source === \\\"extension\\\");\\nconst userScoped = commands.filter((command) => command.sourceInfo.scope === \\\"user\\\");\\n```\\n\\nEach entry has this shape:\\n\\n```typescript\\n{\\n  name: string; // Invokable command name without the leading slash. May be suffixed like \\\"review:1\\\"\\n  description?: string;\\n  source: \\\"extension\\\" | \\\"prompt\\\" | \\\"skill\\\";\\n  sourceInfo: {\\n    path: string;\\n    source: string;\\n    scope: \\\"user\\\" | \\\"project\\\" | \\\"temporary\\\";\\n    origin: \\\"package\\\" | \\\"top-level\\\";\\n    baseDir?: string;\\n  };\\n}\\n```\\n\\nUse `sourceInfo` as the canonical provenance field. Do not infer ownership from command names or from ad hoc path parsing.\\n\\nBuilt-in interactive commands (like `/model` and `/settings`) are not included here. They are handled only in interactive\\nmode and would not execute if sent via `prompt`.\\n\\n### pi.registerMessageRenderer(customType, renderer)\\n\\nRegister a custom TUI renderer for messages with your `customType`. See [Custom UI](#custom-ui).\\n\\n### pi.registerShortcut(shortcut, options)\\n\\nRegister a keyboard shortcut. See [keybindings.md](keybindings.md) for the shortcut format and built-in keybindings.\\n\\n```typescript\\npi.registerShortcut(\\\"ctrl+shift+p\\\", {\\n  description: \\\"Toggle plan mode\\\",\\n  handler: async (ctx) => {\\n    ctx.ui.notify(\\\"Toggled!\\\");\\n  },\\n});\\n```\\n\\n### pi.registerFlag(name, options)\\n\\nRegister a CLI flag.\\n\\n```typescript\\npi.registerFlag(\\\"plan\\\", {\\n  description: \\\"Start in plan mode\\\",\\n  type: \\\"boolean\\\",\\n  default: false,\\n});\\n\\n// Check value\\nif (pi.getFlag(\\\"plan\\\")) {\\n  // Plan mode enabled\\n}\\n```\\n\\n### pi.exec(command, args, options?)\\n\\nExecute a shell command.\\n\\n```typescript\\nconst result = await pi.exec(\\\"git\\\", [\\\"status\\\"], { signal, timeout: 5000 });\\n// result.stdout, result.stderr, result.code, result.killed\\n```\\n\\n### pi.getActiveTools() / pi.getAllTools() / pi.setActiveTools(names)\\n\\nManage active tools. This works for both built-in tools and dynamically registered tools.\\n\\n```typescript\\nconst active = pi.getActiveTools();\\nconst all = pi.getAllTools();\\n// [{\\n//   name: \\\"read\\\",\\n//   description: \\\"Read file contents...\\\",\\n//   parameters: ...,\\n//   promptGuidelines: [\\\"Use read to examine files instead of cat or sed.\\\"],\\n//   sourceInfo: { path: \\\"<builtin:read>\\\", source: \\\"builtin\\\", scope: \\\"temporary\\\", origin: \\\"top-level\\\" }\\n// }, ...]\\nconst names = all.map(t => t.name);\\nconst builtinTools = all.filter((t) => t.sourceInfo.source === \\\"builtin\\\");\\nconst extensionTools = all.filter((t) => t.sourceInfo.source !== \\\"builtin\\\" && t.sourceInfo.source !== \\\"sdk\\\");\\npi.setActiveTools([\\\"read\\\", \\\"bash\\\"]); // Switch to read-only\\n```\\n\\n`pi.getAllTools()` returns `name`, `description`, `parameters`, `promptGuidelines`, and `sourceInfo`.\\n\\nTypical `sourceInfo.source` values:\\n- `builtin` for built-in tools\\n- `sdk` for tools passed via `createAgentSession({ customTools })`\\n- extension source metadata for tools registered by extensions\\n\\n### pi.setModel(model)\\n\\nSet the current model. Returns `false` if no API key is available for the model. See [models.md](models.md) for configuring custom models.\\n\\n```typescript\\nconst model = ctx.modelRegistry.find(\\\"anthropic\\\", \\\"claude-sonnet-4-5\\\");\\nif (model) {\\n  const success = await pi.setModel(model);\\n  if (!success) {\\n    ctx.ui.notify(\\\"No API key for this model\\\", \\\"error\\\");\\n  }\\n}\\n```\\n\\n### pi.getThinkingLevel() / pi.setThinkingLevel(level)\\n\\nGet or set the thinking level. Level is clamped to model capabilities (non-reasoning models always use \\\"off\\\"). Changes emit `thinking_level_select`.\\n\\n```typescript\\nconst current = pi.getThinkingLevel();  // \\\"off\\\" | \\\"minimal\\\" | \\\"low\\\" | \\\"medium\\\" | \\\"high\\\" | \\\"xhigh\\\"\\npi.setThinkingLevel(\\\"high\\\");\\n```\\n\\n### pi.events\\n\\nShared event bus for communication between extensions:\\n\\n```typescript\\npi.events.on(\\\"my:event\\\", (data) => { ... });\\npi.events.emit(\\\"my:event\\\", { ... });\\n```\\n\\n### pi.registerProvider(name, config)\\n\\nRegister or override a model provider dynamically. Useful for proxies, custom endpoints, or team-wide model configurations.\\n\\nCalls made during the extension factory function are queued and applied once the runner initialises. Calls made after that — for example from a command handler following a user setup flow — take effect immediately without requiring a `/reload`.\\n\\nIf you need to discover models from a remote endpoint, prefer an async extension factory over deferring the fetch to `session_start`. pi waits for the factory before startup continues, so the registered models are available immediately, including to `pi --list-models`.\\n\\n```typescript\\n// Register a new provider with custom models\\npi.registerProvider(\\\"my-proxy\\\", {\\n  name: \\\"My Proxy\\\",\\n  baseUrl: \\\"https://proxy.example.com\\\",\\n  apiKey: \\\"$PROXY_API_KEY\\\",  // env var reference\\n  api: \\\"anthropic-messages\\\",\\n  models: [\\n    {\\n      id: \\\"claude-sonnet-4-20250514\\\",\\n      name: \\\"Claude 4 Sonnet (proxy)\\\",\\n      reasoning: false,\\n      input: [\\\"text\\\", \\\"image\\\"],\\n      cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },\\n      contextWindow: 200000,\\n      maxTokens: 16384\\n    }\\n  ]\\n});\\n\\n// Override baseUrl for an existing provider (keeps all models)\\npi.registerProvider(\\\"anthropic\\\", {\\n  baseUrl: \\\"https://proxy.example.com\\\"\\n});\\n\\n// Register provider with OAuth support for /login\\npi.registerProvider(\\\"corporate-ai\\\", {\\n  baseUrl: \\\"https://ai.corp.com\\\",\\n  api: \\\"openai-responses\\\",\\n  models: [...],\\n  oauth: {\\n    name: \\\"Corporate AI (SSO)\\\",\\n    async login(callbacks) {\\n      // Custom OAuth flow\\n      callbacks.onAuth({ url: \\\"https://sso.corp.com/...\\\" });\\n      const code = await callbacks.onPrompt({ message: \\\"Enter code:\\\" });\\n      return { refresh: code, access: code, expires: Date.now() + 3600000 };\\n    },\\n    async refreshToken(credentials) {\\n      // Refresh logic\\n      return credentials;\\n    },\\n    getApiKey(credentials) {\\n      return credentials.access;\\n    }\\n  }\\n});\\n```\\n\\n**Config options:**\\n- `name` - Display name for the provider in UI such as `/login`.\\n- `baseUrl` - API endpoint URL. Required when defining models.\\n- `apiKey` - API key literal, environment interpolation (`$ENV_VAR` or `${ENV_VAR}`), or leading `!command`. Required when defining models (unless `oauth` provided). `$$` escapes `$`, and `$!` escapes a literal `!` without triggering command execution.\\n- `api` - API type: `\\\"anthropic-messages\\\"`, `\\\"openai-completions\\\"`, `\\\"openai-responses\\\"`, etc.\\n- `headers` - Custom headers to include in requests.\\n- `authHeader` - If true, adds `Authorization: Bearer` header automatically.\\n- `models` - Array of model definitions. If provided, replaces all existing models for this provider. Model definitions can set `baseUrl` to override the provider endpoint for that model.\\n- `oauth` - OAuth provider config for `/login` support. When provided, the provider appears in the login menu.\\n- `streamSimple` - Custom streaming implementation for non-standard APIs.\\n\\nSee [custom-provider.md](custom-provider.md) for advanced topics: custom streaming APIs, OAuth details, model definition reference.\\n\\n### pi.unregisterProvider(name)\\n\\nRemove a previously registered provider and its models. Built-in models that were overridden by the provider are restored. Has no effect if the provider was not registered.\\n\\nLike `registerProvider`, this takes effect immediately when called after the initial load phase, so a `/reload` is not required.\\n\\n```typescript\\npi.registerCommand(\\\"my-setup-teardown\\\", {\\n  description: \\\"Remove the custom proxy provider\\\",\\n  handler: async (_args, _ctx) => {\\n    pi.unregisterProvider(\\\"my-proxy\\\");\\n  },\\n});\\n```\\n\\n## State Management\\n\\nExtensions with state should store it in tool result `details` for proper branching support:\\n\\n```typescript\\nexport default function (pi: ExtensionAPI) {\\n  let items: string[] = [];\\n\\n  // Reconstruct state from session\\n  pi.on(\\\"session_start\\\", async (_event, ctx) => {\\n    items = [];\\n    for (const entry of ctx.sessionManager.getBranch()) {\\n      if (entry.type === \\\"message\\\" && entry.message.role === \\\"toolResult\\\") {\\n        if (entry.message.toolName === \\\"my_tool\\\") {\\n          items = entry.message.details?.items ?? [];\\n        }\\n      }\\n    }\\n  });\\n\\n  pi.registerTool({\\n    name: \\\"my_tool\\\",\\n    // ...\\n    async execute(toolCallId, params, signal, onUpdate, ctx) {\\n      items.push(\\\"new item\\\");\\n      return {\\n        content: [{ type: \\\"text\\\", text: \\\"Added\\\" }],\\n        details: { items: [...items] },  // Store for reconstruction\\n      };\\n    },\\n  });\\n}\\n```\\n\\n## Custom Tools\\n\\nRegister tools the LLM can call via `pi.registerTool()`. Tools appear in the system prompt and can have custom rendering.\\n\\nUse `promptSnippet` for a short one-line entry in the `Available tools` section in the default system prompt. If omitted, custom tools are left out of that section.\\n\\nUse `promptGuidelines` to add tool-specific bullets to the default system prompt `Guidelines` section. These bullets are included only while the tool is active (for example, after `pi.setActiveTools([...])`).\\n\\n**Important:** `promptGuidelines` bullets are appended flat to the `Guidelines` section with no tool name prefix or grouping. Each guideline must name the tool it refers to — avoid \\\"Use this tool when...\\\" because the LLM cannot tell which tool \\\"this\\\" means. Write \\\"Use my_tool when...\\\" instead.\\n\\nNote: Some models are idiots and include the @ prefix in tool path arguments. Built-in tools strip a leading @ before resolving paths. If your custom tool accepts a path, normalize a leading @ as well.\\n\\nIf your custom tool mutates files, use `withFileMutationQueue()` so it participates in the same per-file queue as built-in `edit` and `write`. This matters because tool calls run in parallel by default. Without the queue, two tools can read the same old file contents, compute different updates, and then whichever write lands last overwrites the other.\\n\\nExample failure case: your custom tool edits `foo.ts` while built-in `edit` also changes `foo.ts` in the same assistant turn. If your tool does not participate in the queue, both can read the original `foo.ts`, apply separate changes, and one of those changes is lost.\\n\\nPass the real target file path to `withFileMutationQueue()`, not the raw user argument. Resolve it to an absolute path first, relative to `ctx.cwd` or your tool's working directory. For existing files, the helper canonicalizes through `realpath()`, so symlink aliases for the same file share one queue. For new files, it falls back to the resolved absolute path because there is nothing to `realpath()` yet.\\n\\nQueue the entire mutation window on that target path. That includes read-modify-write logic, not just the final write.\\n\\n```typescript\\nimport { withFileMutationQueue } from \\\"@earendil-works/pi-coding-agent\\\";\\nimport { mkdir, readFile, writeFile } from \\\"node:fs/promises\\\";\\nimport { dirname, resolve } from \\\"node:path\\\";\\n\\nasync execute(_toolCallId, params, _signal, _onUpdate, ctx) {\\n  const absolutePath = resolve(ctx.cwd, params.path);\\n\\n  return withFileMutationQueue(absolutePath, async () => {\\n    await mkdir(dirname(absolutePath), { recursive: true });\\n    const current = await readFile(absolutePath, \\\"utf8\\\");\\n    const next = current.replace(params.oldText, params.newText);\\n    await writeFile(absolutePath, next, \\\"utf8\\\");\\n\\n    return {\\n      content: [{ type: \\\"text\\\", text: `Updated ${params.path}` }],\\n      details: {},\\n    };\\n  });\\n}\\n```\\n\\n### Tool Definition\\n\\n```typescript\\nimport { Type } from \\\"typebox\\\";\\nimport { StringEnum } from \\\"@earendil-works/pi-ai\\\";\\nimport { Text } from \\\"@earendil-works/pi-tui\\\";\\n\\npi.registerTool({\\n  name: \\\"my_tool\\\",\\n  label: \\\"My Tool\\\",\\n  description: \\\"What this tool does (shown to LLM)\\\",\\n  promptSnippet: \\\"List or add items in the project todo list\\\",\\n  promptGuidelines: [\\n    \\\"Use my_tool for todo planning instead of direct file edits when the user asks for a task list.\\\"\\n  ],\\n  parameters: Type.Object({\\n    action: StringEnum([\\\"list\\\", \\\"add\\\"] as const),  // Use StringEnum for Google compatibility\\n    text: Type.Optional(Type.String()),\\n  }),\\n  prepareArguments(args) {\\n    if (!args || typeof args !== \\\"object\\\") return args;\\n    const input = args as { action?: string; oldAction?: string };\\n    if (typeof input.oldAction === \\\"string\\\" && input.action === undefined) {\\n      return { ...input, action: input.oldAction };\\n    }\\n    return args;\\n  },\\n\\n  async execute(toolCallId, params, signal, onUpdate, ctx) {\\n    // Check for cancellation\\n    if (signal?.aborted) {\\n      return { content: [{ type: \\\"text\\\", text: \\\"Cancelled\\\" }] };\\n    }\\n\\n    // Stream progress updates\\n    onUpdate?.({\\n      content: [{ type: \\\"text\\\", text: \\\"Working...\\\" }],\\n      details: { progress: 50 },\\n    });\\n\\n    // Run commands via pi.exec (captured from extension closure)\\n    const result = await pi.exec(\\\"some-command\\\", [], { signal });\\n\\n    // Return result\\n    return {\\n      content: [{ type: \\\"text\\\", text: \\\"Done\\\" }],  // Sent to LLM\\n      details: { data: result },                   // For rendering & state\\n      // Optional: stop after this tool batch when every finalized tool result\\n      // in the batch also returns terminate: true.\\n      terminate: true,\\n    };\\n  },\\n\\n  // Optional: Custom rendering\\n  renderCall(args, theme, context) { ... },\\n  renderResult(result, options, theme, context) { ... },\\n});\\n```\\n\\n**Signaling errors:** To mark a tool execution as failed (sets `isError: true` on the result and reports it to the LLM), throw an error from `execute`. Returning a value never sets the error flag regardless of what properties you include in the return object.\\n\\n**Early termination:** Return `terminate: true` from `execute()` to hint that the automatic follow-up LLM call should be skipped after the current tool batch. This only takes effect when every finalized tool result in that batch is terminating. See [examples/extensions/structured-output.ts](../examples/extensions/structured-output.ts) for a minimal example where the agent ends on a final structured-output tool call.\\n\\n```typescript\\n// Correct: throw to signal an error\\nasync execute(toolCallId, params) {\\n  if (!isValid(params.input)) {\\n    throw new Error(`Invalid input: ${params.input}`);\\n  }\\n  return { content: [{ type: \\\"text\\\", text: \\\"OK\\\" }], details: {} };\\n}\\n```\\n\\n**Important:** Use `StringEnum` from `@earendil-works/pi-ai` for string enums. `Type.Union`/`Type.Literal` doesn't work with Google's API.\\n\\n**Argument preparation:** `prepareArguments(args)` is optional. If defined, it runs before schema validation and before `execute()`. Use it to mimic an older accepted input shape when pi resumes an older session whose stored tool call arguments no longer match the current schema. Return the object you want validated against `parameters`. Keep the public schema strict. Do not add deprecated compatibility fields to `parameters` just to keep old resumed sessions working.\\n\\nExample: an older session may contain an `edit` tool call with top-level `oldText` and `newText`, while the current schema only accepts `edits: [{ oldText, newText }]`.\\n\\n```typescript\\npi.registerTool({\\n  name: \\\"edit\\\",\\n  label: \\\"Edit\\\",\\n  description: \\\"Edit a single file using exact text replacement\\\",\\n  parameters: Type.Object({\\n    path: Type.String(),\\n    edits: Type.Array(\\n      Type.Object({\\n        oldText: Type.String(),\\n        newText: Type.String(),\\n      }),\\n    ),\\n  }),\\n  prepareArguments(args) {\\n    if (!args || typeof args !== \\\"object\\\") return args;\\n\\n    const input = args as {\\n      path?: string;\\n      edits?: Array<{ oldText: string; newText: string }>;\\n      oldText?: unknown;\\n      newText?: unknown;\\n    };\\n\\n    if (typeof input.oldText !== \\\"string\\\" || typeof input.newText !== \\\"string\\\") {\\n      return args;\\n    }\\n\\n    return {\\n      ...input,\\n      edits: [...(input.edits ?? []), { oldText: input.oldText, newText: input.newText }],\\n    };\\n  },\\n  async execute(toolCallId, params, signal, onUpdate, ctx) {\\n    // params now matches the current schema\\n    return {\\n      content: [{ type: \\\"text\\\", text: `Applying ${params.edits.length} edit block(s)` }],\\n      details: {},\\n    };\\n  },\\n});\\n```\\n\\n### Overriding Built-in Tools\\n\\nExtensions can override built-in tools (`read`, `bash`, `edit`, `write`, `grep`, `find`, `ls`) by registering a tool with the same name. Interactive mode displays a warning when this happens.\\n\\n```bash\\n# Extension's read tool replaces built-in read\\npi -e ./tool-override.ts\\n```\\n\\nAlternatively, use `--no-builtin-tools` to start without any built-in tools while keeping extension tools enabled:\\n```bash\\n# No built-in tools, only extension tools\\npi --no-builtin-tools -e ./my-extension.ts\\n```\\n\\nSee [examples/extensions/tool-override.ts](../examples/extensions/tool-override.ts) for a complete example that overrides `read` with logging and access control.\\n\\n**Rendering:** Built-in renderer inheritance is resolved per slot. Execution override and rendering override are independent. If your override omits `renderCall`, the built-in `renderCall` is used. If your override omits `renderResult`, the built-in `renderResult` is used. If your override omits both, the built-in renderer is used automatically (syntax highlighting, diffs, etc.). This lets you wrap built-in tools for logging or access control without reimplementing the UI.\\n\\n**Prompt metadata:** `promptSnippet` and `promptGuidelines` are not inherited from the built-in tool. If your override should keep those prompt instructions, define the [result truncated: 453461 bytes exceeds the 131072-byte output limit; return a smaller value]",
